--
-- Name: cleanup_old_metrics(integer); Type: FUNCTION; Schema: admin_dashboard; Owner: postgres
--

CREATE FUNCTION admin_dashboard.cleanup_old_metrics(p_retention_days integer DEFAULT 30) RETURNS TABLE(deleted_count integer, status_message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_deleted_count INTEGER;
    v_cutoff_date TIMESTAMPTZ;
BEGIN
    v_cutoff_date := NOW() - (p_retention_days || ' days')::INTERVAL;

    DELETE FROM admin_dashboard.metrics_history
    WHERE recorded_at < v_cutoff_date;

    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

    RETURN QUERY SELECT
        v_deleted_count,
        format('Deleted %s metrics older than %s days (before %s)',
               v_deleted_count, p_retention_days, v_cutoff_date);
END;
$$;


ALTER FUNCTION admin_dashboard.cleanup_old_metrics(p_retention_days integer) OWNER TO postgres;

