--
-- Name: log_system_event(text, text, jsonb, text); Type: FUNCTION; Schema: audit_logging; Owner: postgres
--

CREATE FUNCTION audit_logging.log_system_event(p_event_type text, p_event_source text, p_event_data jsonb DEFAULT NULL::jsonb, p_severity text DEFAULT 'INFO'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'audit_logging'
    AS $$
DECLARE
    v_event_id UUID;
    v_valid_severity BOOLEAN;
    v_log_level TEXT;
BEGIN
    -- Validate severity level
    v_valid_severity := p_severity IN ('DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL');

    IF NOT v_valid_severity THEN
        RAISE EXCEPTION 'Invalid severity level: %', p_severity;
    END IF;

    -- Map severity to system_logs.log_level CHECK values (TRACE, DEBUG, INFO, WARN, ERROR, FATAL)
    v_log_level := CASE p_severity
        WHEN 'WARNING' THEN 'WARN'
        WHEN 'CRITICAL' THEN 'FATAL'
        ELSE p_severity
    END;

    -- Insert system event into system_logs with correct column names
    INSERT INTO audit_logging.system_logs (
        log_level,
        message,
        module_name,
        extra_data,
        created_at
    ) VALUES (
        v_log_level,
        p_event_type,
        p_event_source,
        COALESCE(p_event_data, '{}'::jsonb),
        NOW()
    )
    RETURNING id INTO v_event_id;

    -- Return the created event ID
    RETURN v_event_id;

EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Error logging system event: %', SQLERRM;
    RETURN NULL;
END;
$$;


ALTER FUNCTION audit_logging.log_system_event(p_event_type text, p_event_source text, p_event_data jsonb, p_severity text) OWNER TO postgres;

--
-- Name: FUNCTION log_system_event(p_event_type text, p_event_source text, p_event_data jsonb, p_severity text); Type: COMMENT; Schema: audit_logging; Owner: postgres
--

COMMENT ON FUNCTION audit_logging.log_system_event(p_event_type text, p_event_source text, p_event_data jsonb, p_severity text) IS 'Logs system events for monitoring and debugging purposes.
Parameters:
  - p_event_type: Type of event mapped to message column (e.g., ''DATABASE_BACKUP_START'', ''API_ERROR'')
  - p_event_source: Source component mapped to module_name column
  - p_event_data: Optional JSONB data mapped to extra_data column
  - p_severity: DEBUG, INFO, WARNING, ERROR, CRITICAL (mapped to log_level: WARNING→WARN, CRITICAL→FATAL)
Returns:
  - UUID of the created system log entry, or NULL on error
Example:
  SELECT log_system_event(
    ''API_REQUEST_TIMEOUT''::TEXT,
    ''auth_service''::TEXT,
    jsonb_build_object(''user_id'', 123, ''endpoint'', ''/api/auth/login''),
    ''WARNING''::TEXT
  );';


--
-- Name: resolve_pending_initialization(uuid, uuid, text); Type: FUNCTION; Schema: audit_logging; Owner: postgres
--

CREATE FUNCTION audit_logging.resolve_pending_initialization(p_user_id uuid, p_resolved_by uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    UPDATE audit_logging.pending_user_initializations
    SET status = 'resolved',
        resolved_at = gamilit.now_mexico(),
        resolved_by = p_resolved_by,
        resolution_notes = p_notes,
        updated_at = gamilit.now_mexico()
    WHERE user_id = p_user_id
      AND status IN ('pending', 'retrying', 'failed');

    RETURN FOUND;
END;
$$;


ALTER FUNCTION audit_logging.resolve_pending_initialization(p_user_id uuid, p_resolved_by uuid, p_notes text) OWNER TO postgres;

--
-- Name: FUNCTION resolve_pending_initialization(p_user_id uuid, p_resolved_by uuid, p_notes text); Type: COMMENT; Schema: audit_logging; Owner: postgres
--

COMMENT ON FUNCTION audit_logging.resolve_pending_initialization(p_user_id uuid, p_resolved_by uuid, p_notes text) IS 'Marca un registro de inicialización pendiente como resuelto';


--
-- Name: retry_pending_initializations(integer); Type: FUNCTION; Schema: audit_logging; Owner: postgres
--

CREATE FUNCTION audit_logging.retry_pending_initializations(p_batch_size integer DEFAULT 10) RETURNS TABLE(user_id uuid, retry_status text, error_message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'audit_logging', 'gamilit', 'gamification_system', 'social_features', 'auth_management', 'public'
    AS $$
DECLARE
    rec RECORD;
    v_result TEXT;
    v_error TEXT;
BEGIN
    -- =========================================================================
    -- Procesar registros pendientes que pueden ser reintentados
    -- =========================================================================
    FOR rec IN
        SELECT *
        FROM audit_logging.pending_user_initialization pui
        WHERE pui.status IN ('pending', 'retrying')
          AND pui.retry_count < pui.max_retries
          AND (pui.next_retry_at IS NULL OR pui.next_retry_at <= NOW())
        ORDER BY pui.created_at ASC
        LIMIT p_batch_size
    LOOP
        BEGIN
            -- Marcar como en proceso
            UPDATE audit_logging.pending_user_initialization
            SET status = 'retrying',
                last_retry_at = gamilit.now_mexico(),
                updated_at = gamilit.now_mexico()
            WHERE id = rec.id;

            -- =========================================================
            -- Reintentar segun el codigo de error original
            -- =========================================================
            IF rec.error_code = 'P0-001' OR rec.trigger_name LIKE '%manual_review%' THEN
                -- Error en creacion de ManualReview
                -- Intentar crear el ManualReview faltante
                PERFORM progress_tracking.create_manual_review_on_submission();

            ELSIF rec.function_name LIKE '%initialize_user_stats%' THEN
                -- Error en inicializacion de user_stats
                PERFORM gamilit.initialize_user_stats_for_user(rec.user_id);

            ELSIF rec.function_name LIKE '%assign_default_classroom%' THEN
                -- Error en asignacion de classroom
                PERFORM gamilit.assign_default_classroom_for_user(rec.user_id);

            ELSIF rec.function_name LIKE '%initialize_user_missions%' THEN
                -- Error en inicializacion de misiones
                PERFORM gamilit.initialize_user_missions(rec.user_id);

            ELSE
                -- Intento generico: reinicializar todo
                -- Verificar si ya tiene user_stats
                IF NOT EXISTS (
                    SELECT 1 FROM gamification_system.user_stats
                    WHERE user_id = rec.user_id
                ) THEN
                    PERFORM gamilit.initialize_user_stats_for_user(rec.user_id);
                END IF;

                -- Verificar si ya tiene classroom
                IF NOT EXISTS (
                    SELECT 1 FROM social_features.classroom_members
                    WHERE student_id = rec.user_id AND is_active = TRUE
                ) THEN
                    PERFORM gamilit.assign_default_classroom_for_user(rec.user_id);
                END IF;
            END IF;

            -- =========================================================
            -- Marcar como resuelto
            -- =========================================================
            UPDATE audit_logging.pending_user_initialization
            SET status = 'resolved',
                resolved_at = gamilit.now_mexico(),
                resolution_notes = 'Reintento automatico exitoso',
                updated_at = gamilit.now_mexico()
            WHERE id = rec.id;

            user_id := rec.user_id;
            retry_status := 'SUCCESS';
            error_message := NULL;
            RETURN NEXT;

        EXCEPTION WHEN OTHERS THEN
            -- =========================================================
            -- Manejar error: incrementar contador y programar siguiente retry
            -- =========================================================
            v_error := SQLERRM;

            UPDATE audit_logging.pending_user_initialization
            SET retry_count = retry_count + 1,
                last_retry_at = gamilit.now_mexico(),
                next_retry_at = gamilit.now_mexico() + INTERVAL '5 minutes' * (retry_count + 1),
                error_message = v_error,
                status = CASE
                    WHEN retry_count + 1 >= max_retries THEN 'failed'
                    ELSE 'pending'
                END,
                updated_at = gamilit.now_mexico()
            WHERE id = rec.id;

            user_id := rec.user_id;
            retry_status := CASE
                WHEN rec.retry_count + 1 >= rec.max_retries THEN 'FAILED_PERMANENT'
                ELSE 'FAILED_RETRY_SCHEDULED'
            END;
            error_message := v_error;
            RETURN NEXT;
        END;
    END LOOP;
END;
$$;


ALTER FUNCTION audit_logging.retry_pending_initializations(p_batch_size integer) OWNER TO postgres;

--
-- Name: FUNCTION retry_pending_initializations(p_batch_size integer); Type: COMMENT; Schema: audit_logging; Owner: postgres
--

COMMENT ON FUNCTION audit_logging.retry_pending_initializations(p_batch_size integer) IS 'Reintenta la inicializacion de usuarios que fallaron. Procesa un batch de registros pendientes y retorna el resultado de cada intento. Usar via cron job o llamar manualmente cuando se detecten usuarios sin inicializar.';


--
-- Name: assign_role_to_user(uuid, auth_management.gamilit_role, jsonb, uuid); Type: FUNCTION; Schema: auth_management; Owner: postgres
--

CREATE FUNCTION auth_management.assign_role_to_user(p_user_id uuid, p_role auth_management.gamilit_role, p_permissions jsonb DEFAULT '{}'::jsonb, p_assigned_by uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_role_id uuid;
    v_tenant_id uuid;
    v_current_user_id uuid;
BEGIN
    -- Get current user
    v_current_user_id := COALESCE(p_assigned_by, gamilit.get_current_user_id());

    -- Only super admins can assign roles
    IF NOT gamilit.is_super_admin() THEN
        RAISE EXCEPTION 'Only super admins can assign roles';
    END IF;

    -- Get user's tenant_id
    SELECT tenant_id INTO v_tenant_id
    FROM auth_management.profiles
    WHERE id = p_user_id;

    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'User profile not found';
    END IF;

    -- Check if user already has this role
    SELECT id INTO v_role_id
    FROM auth_management.user_roles
    WHERE user_id = p_user_id
    AND role = p_role
    AND is_active = true;

    IF v_role_id IS NOT NULL THEN
        RAISE EXCEPTION 'User already has this role';
    END IF;

    -- Insert new role
    INSERT INTO auth_management.user_roles (
        id,
        tenant_id,
        user_id,
        role,
        permissions,
        assigned_by,
        assigned_at,
        is_active,
        created_at,
        updated_at
    )
    VALUES (
        uuid_generate_v4(),
        v_tenant_id,
        p_user_id,
        p_role,
        p_permissions,
        v_current_user_id,
        NOW(),
        true,
        NOW(),
        NOW()
    )
    RETURNING id INTO v_role_id;

    -- Log audit event
    PERFORM audit_logging.log_audit_event(
        v_current_user_id,
        'ASSIGN_ROLE',
        'auth_management.user_roles',
        v_role_id,
        NULL,
        jsonb_build_object(
            'user_id', p_user_id,
            'role', p_role,
            'permissions', p_permissions
        )
    );

    RETURN v_role_id;
END;
$$;


ALTER FUNCTION auth_management.assign_role_to_user(p_user_id uuid, p_role auth_management.gamilit_role, p_permissions jsonb, p_assigned_by uuid) OWNER TO postgres;

--
