--
-- Name: hash_token(text); Type: FUNCTION; Schema: auth_management; Owner: postgres
--

CREATE FUNCTION auth_management.hash_token(p_token text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$
BEGIN
    IF p_token IS NULL OR p_token = '' THEN
        RAISE EXCEPTION 'Token cannot be NULL or empty';
    END IF;

    -- Hash the token using SHA-256
    RETURN encode(digest(p_token, 'sha256'), 'hex');
END;
$$;


ALTER FUNCTION auth_management.hash_token(p_token text) OWNER TO postgres;

