Usage: SELECT communication.add_conversation_participant(conv_uuid, user_uuid, ''member'');';


--
-- Name: create_conversation(character varying, character varying, uuid, uuid[], uuid); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.create_conversation(p_title character varying, p_conversation_type character varying, p_created_by uuid, p_participant_ids uuid[], p_classroom_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_conversation_id UUID;
    v_participant_id UUID;
BEGIN
    -- Insert conversation
    INSERT INTO communication.conversations (
        title,
        conversation_type,
        created_by,
        classroom_id
    ) VALUES (
        p_title,
        p_conversation_type,
        p_created_by,
        p_classroom_id
    )
    RETURNING id INTO v_conversation_id;

    -- Add creator as owner
    INSERT INTO communication.conversation_participants (
        conversation_id,
        user_id,
        role
    ) VALUES (
        v_conversation_id,
        p_created_by,
        'owner'
    );

    -- Add other participants as members
    FOREACH v_participant_id IN ARRAY p_participant_ids LOOP
        IF v_participant_id != p_created_by THEN
            INSERT INTO communication.conversation_participants (
                conversation_id,
                user_id,
                role
            ) VALUES (
                v_conversation_id,
                v_participant_id,
                'member'
            );
        END IF;
    END LOOP;

    RETURN v_conversation_id;
END;
$$;


