--
-- Name: get_total_unread_conversations(uuid); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.get_total_unread_conversations(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COALESCE(SUM(unread_count), 0)::INTEGER
    INTO v_count
    FROM communication.conversation_participants cp
    JOIN communication.conversations c ON c.id = cp.conversation_id
    WHERE cp.user_id = p_user_id
      AND cp.is_active = TRUE
      AND cp.is_muted = FALSE
      AND c.is_archived = FALSE;

    RETURN v_count;
END;
$$;


