-- Name: FUNCTION increment_unread_for_conversation(p_conversation_id uuid, p_sender_id uuid, p_message_preview text); Type: COMMENT; Schema: communication; Owner: postgres
--

COMMENT ON FUNCTION communication.increment_unread_for_conversation(p_conversation_id uuid, p_sender_id uuid, p_message_preview text) IS 'Increment unread count for all participants except sender when a new message is sent.
Usage: SELECT communication.increment_unread_for_conversation(conv_uuid, sender_uuid, ''preview text'');';


--
-- Name: mark_conversation_as_read(uuid, uuid, uuid); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.mark_conversation_as_read(p_conversation_id uuid, p_user_id uuid, p_last_message_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_updated INTEGER;
BEGIN
    UPDATE communication.conversation_participants
    SET last_read_at = NOW(),
        last_read_message_id = COALESCE(p_last_message_id, last_read_message_id),
        unread_count = 0,
        updated_at = NOW()
    WHERE conversation_id = p_conversation_id
      AND user_id = p_user_id
      AND is_active = TRUE;

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated > 0;
END;
$$;


