Usage: SELECT communication.mark_conversation_as_read(conv_uuid, user_uuid);';


--
-- Name: mark_conversation_read(uuid, uuid); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.mark_conversation_read(p_user_id uuid, p_thread_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_updated INTEGER;
BEGIN
    UPDATE communication.messages
    SET is_read = TRUE,
        read_at = NOW()
    WHERE recipient_id = p_user_id
      AND thread_id = p_thread_id
      AND is_read = FALSE
      AND is_deleted = FALSE;

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated;
END;
$$;


