--

CREATE FUNCTION communication.mark_message_read_for_user(p_message_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_updated BOOLEAN := FALSE;
BEGIN
    UPDATE communication.message_participants
    SET is_read = TRUE,
        read_at = NOW()
    WHERE message_id = p_message_id
      AND user_id = p_user_id
      AND is_read = FALSE;

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated > 0;
END;
$$;


