-- Name: remove_conversation_participant(uuid, uuid); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.remove_conversation_participant(p_conversation_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_updated INTEGER;
BEGIN
    UPDATE communication.conversation_participants
    SET is_active = FALSE,
        left_at = NOW(),
        updated_at = NOW()
    WHERE conversation_id = p_conversation_id
      AND user_id = p_user_id
      AND is_active = TRUE;

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated > 0;
END;
$$;


