--
-- Name: apply_moderation_rules(uuid, text, character varying); Type: FUNCTION; Schema: content_management; Owner: postgres
--

CREATE FUNCTION content_management.apply_moderation_rules(p_content_id uuid, p_content_text text, p_entity_type character varying) RETURNS TABLE(rule_matched boolean, rule_id uuid, rule_name character varying, action character varying, severity character varying, auto_executed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_rule RECORD;
    v_matched BOOLEAN;
    v_has_matches BOOLEAN := false;
BEGIN
    -- Si no hay contenido, no hay nada que moderar
    IF p_content_text IS NULL OR p_content_text = '' THEN
        RETURN QUERY SELECT false, NULL::UUID, NULL::VARCHAR, NULL::VARCHAR, NULL::VARCHAR, false;
        RETURN;
    END IF;

    -- Iterar sobre reglas activas ordenadas por prioridad y severidad
    FOR v_rule IN
        SELECT *
        FROM content_management.moderation_rules
        WHERE is_active = true
          AND target_entity = p_entity_type
        ORDER BY priority DESC, severity DESC, created_at ASC
    LOOP
        v_matched := false;

        -- Evaluar según tipo de regla
        CASE v_rule.rule_type
            WHEN 'keyword' THEN
                v_matched := content_management.check_keyword_rule(
                    p_content_text,
                    v_rule.rule_config
                );

            WHEN 'pattern' THEN
                v_matched := content_management.check_pattern_rule(
                    p_content_text,
                    v_rule.rule_config
                );

            WHEN 'length' THEN
                -- Verificar longitud del texto
                DECLARE
                    v_min_length INTEGER;
                    v_max_length INTEGER;
                    v_text_length INTEGER;
                BEGIN
                    v_min_length := COALESCE((v_rule.rule_config->>'min_length')::INTEGER, 0);
                    v_max_length := COALESCE((v_rule.rule_config->>'max_length')::INTEGER, 999999);
                    v_text_length := LENGTH(p_content_text);

                    v_matched := v_text_length < v_min_length OR v_text_length > v_max_length;
                END;

            ELSE
                -- Tipo de regla no soportado
                CONTINUE;
        END CASE;

        -- Si la regla coincidió, aplicar acción
        IF v_matched THEN
            v_has_matches := true;

            -- Aplicar acción según el tipo
            IF v_rule.action = 'flag' THEN
                -- Flaggear contenido para revisión
                INSERT INTO content_management.flagged_content (
                    content_id,
                    flagged_by_system,
                    reason,
                    priority,
                    status,
                    created_at
                ) VALUES (
                    p_content_id,
                    true,
                    'Auto-moderación: ' || v_rule.rule_name,
                    v_rule.severity,
                    'pending',
                    gamilit.now_mexico()
                )
                ON CONFLICT (content_id) DO UPDATE
                SET
                    reason = EXCLUDED.reason,
                    priority = EXCLUDED.priority,
                    updated_at = gamilit.now_mexico();

            ELSIF v_rule.action = 'block' AND v_rule.auto_execute THEN
                -- Bloquear contenido automáticamente
                -- Nota: Esto requiere que exista una tabla 'content' o similar
                -- con una columna 'status'. Ajustar según estructura real.
                -- Por ahora solo lo flaggeamos con alta prioridad
                INSERT INTO content_management.flagged_content (
                    content_id,
                    flagged_by_system,
                    reason,
                    priority,
                    status,
                    created_at
                ) VALUES (
                    p_content_id,
                    true,
                    'AUTO-BLOCKED: ' || v_rule.rule_name,
                    'critical',
                    'blocked',
                    gamilit.now_mexico()
                )
                ON CONFLICT (content_id) DO UPDATE
                SET
                    reason = EXCLUDED.reason,
                    status = 'blocked',
                    updated_at = gamilit.now_mexico();

            ELSIF v_rule.action = 'notify' THEN
                -- Enviar notificación a moderadores
                -- (Aquí se puede integrar con el sistema de notificaciones)
                INSERT INTO content_management.flagged_content (
                    content_id,
                    flagged_by_system,
                    reason,
                    priority,
                    status,
                    created_at
                ) VALUES (
                    p_content_id,
                    true,
                    'NOTIFY: ' || v_rule.rule_name,
                    v_rule.severity,
                    'review_required',
                    gamilit.now_mexico()
                )
                ON CONFLICT (content_id) DO UPDATE
                SET
                    reason = EXCLUDED.reason,
                    updated_at = gamilit.now_mexico();
            END IF;

            -- Retornar información del match
            RETURN QUERY SELECT
                true,
                v_rule.id,
                v_rule.rule_name::VARCHAR,
                v_rule.action::VARCHAR,
                v_rule.severity::VARCHAR,
                v_rule.auto_execute;

            -- Si la regla se auto-ejecutó y no requiere más revisión, detener
            IF v_rule.auto_execute AND NOT v_rule.require_review THEN
                RETURN;
            END IF;
        END IF;
    END LOOP;

    -- Si no hubo matches, retornar registro con false
    IF NOT v_has_matches THEN
        RETURN QUERY SELECT
            false,
            NULL::UUID,
            NULL::VARCHAR,
            NULL::VARCHAR,
            NULL::VARCHAR,
            false;
    END IF;

    RETURN;
END;
$$;


ALTER FUNCTION content_management.apply_moderation_rules(p_content_id uuid, p_content_text text, p_entity_type character varying) OWNER TO postgres;

--
-- Name: FUNCTION apply_moderation_rules(p_content_id uuid, p_content_text text, p_entity_type character varying); Type: COMMENT; Schema: content_management; Owner: postgres
--

COMMENT ON FUNCTION content_management.apply_moderation_rules(p_content_id uuid, p_content_text text, p_entity_type character varying) IS 'Aplica todas las reglas de moderación activas a un contenido y ejecuta las acciones correspondientes';


--
-- Name: auto_moderate_content(uuid, text, character varying); Type: FUNCTION; Schema: content_management; Owner: postgres
--

CREATE FUNCTION content_management.auto_moderate_content(p_content_id uuid, p_content_text text, p_entity_type character varying DEFAULT 'content'::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_results RECORD;
    v_matches JSONB := '[]'::jsonb;
    v_has_critical BOOLEAN := false;
    v_should_block BOOLEAN := false;
BEGIN
    -- Aplicar reglas de moderación
    FOR v_results IN
        SELECT *
        FROM content_management.apply_moderation_rules(
            p_content_id,
            p_content_text,
            p_entity_type
        )
        WHERE rule_matched = true
    LOOP
        -- Agregar match al resultado
        v_matches := v_matches || jsonb_build_object(
            'rule_id', v_results.rule_id,
            'rule_name', v_results.rule_name,
            'action', v_results.action,
            'severity', v_results.severity,
            'auto_executed', v_results.auto_executed
        );

        -- Verificar si hay reglas críticas
        IF v_results.severity = 'critical' THEN
            v_has_critical := true;
        END IF;

        -- Verificar si debe bloquearse
        IF v_results.action = 'block' AND v_results.auto_executed THEN
            v_should_block := true;
        END IF;
    END LOOP;

    -- Retornar resumen en JSON
    RETURN jsonb_build_object(
        'content_id', p_content_id,
        'moderated', jsonb_array_length(v_matches) > 0,
        'matches_count', jsonb_array_length(v_matches),
        'has_critical', v_has_critical,
        'should_block', v_should_block,
        'matches', v_matches
    );
END;
$$;


ALTER FUNCTION content_management.auto_moderate_content(p_content_id uuid, p_content_text text, p_entity_type character varying) OWNER TO postgres;

--
-- Name: FUNCTION auto_moderate_content(p_content_id uuid, p_content_text text, p_entity_type character varying); Type: COMMENT; Schema: content_management; Owner: postgres
--

COMMENT ON FUNCTION content_management.auto_moderate_content(p_content_id uuid, p_content_text text, p_entity_type character varying) IS 'Función simplificada que modera contenido y retorna resultado en formato JSON';


--
-- Name: check_keyword_rule(text, jsonb); Type: FUNCTION; Schema: content_management; Owner: postgres
--

CREATE FUNCTION content_management.check_keyword_rule(p_text text, p_config jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_keywords TEXT[];
    v_case_sensitive BOOLEAN;
    v_match_whole_word BOOLEAN;
    v_keyword TEXT;
    v_search_text TEXT;
    v_search_keyword TEXT;
    v_pattern TEXT;
BEGIN
    -- Si el texto está vacío, no hay match
    IF p_text IS NULL OR p_text = '' THEN
        RETURN false;
    END IF;

    -- Extraer configuración
    v_keywords := ARRAY(SELECT jsonb_array_elements_text(p_config->'keywords'));
    v_case_sensitive := COALESCE((p_config->>'case_sensitive')::BOOLEAN, false);
    v_match_whole_word := COALESCE((p_config->>'match_whole_word')::BOOLEAN, true);

    -- Si no hay keywords, no hay match
    IF array_length(v_keywords, 1) IS NULL THEN
        RETURN false;
    END IF;

    -- Preparar texto para búsqueda
    v_search_text := CASE
        WHEN v_case_sensitive THEN p_text
        ELSE LOWER(p_text)
    END;

    -- Buscar cada keyword
    FOREACH v_keyword IN ARRAY v_keywords LOOP
        v_search_keyword := CASE
            WHEN v_case_sensitive THEN v_keyword
            ELSE LOWER(v_keyword)
        END;

        IF v_match_whole_word THEN
            -- Buscar palabra completa usando regex
            v_pattern := '\y' || v_search_keyword || '\y';
            IF v_search_text ~ v_pattern THEN
                RETURN true;
            END IF;
        ELSE
            -- Buscar substring
            IF v_search_text LIKE '%' || v_search_keyword || '%' THEN
                RETURN true;
            END IF;
        END IF;
    END LOOP;

    RETURN false;
END;
$$;


ALTER FUNCTION content_management.check_keyword_rule(p_text text, p_config jsonb) OWNER TO postgres;

--
-- Name: FUNCTION check_keyword_rule(p_text text, p_config jsonb); Type: COMMENT; Schema: content_management; Owner: postgres
--

COMMENT ON FUNCTION content_management.check_keyword_rule(p_text text, p_config jsonb) IS 'Verifica si un texto contiene keywords prohibidas según configuración JSON';


--
-- Name: check_pattern_rule(text, jsonb); Type: FUNCTION; Schema: content_management; Owner: postgres
--

CREATE FUNCTION content_management.check_pattern_rule(p_text text, p_config jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_regex TEXT;
    v_case_sensitive BOOLEAN;
    v_flags TEXT;
BEGIN
    -- Si el texto está vacío, no hay match
    IF p_text IS NULL OR p_text = '' THEN
        RETURN false;
    END IF;

    -- Extraer regex de la configuración
    v_regex := p_config->>'regex';

    IF v_regex IS NULL OR v_regex = '' THEN
        RETURN false;
    END IF;

    -- Extraer case sensitivity
    v_case_sensitive := COALESCE((p_config->>'case_sensitive')::BOOLEAN, true);

    -- Construir flags para regex
    v_flags := CASE
        WHEN v_case_sensitive THEN ''
        ELSE 'i' -- case insensitive flag
    END;

    -- Evaluar regex
    BEGIN
        IF v_flags = '' THEN
            RETURN p_text ~ v_regex;
        ELSE
            RETURN p_text ~* v_regex; -- case insensitive operator
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            -- Si el regex es inválido, retornar false
            RAISE WARNING 'Invalid regex pattern: %', v_regex;
            RETURN false;
    END;
END;
$$;


ALTER FUNCTION content_management.check_pattern_rule(p_text text, p_config jsonb) OWNER TO postgres;

--
-- Name: FUNCTION check_pattern_rule(p_text text, p_config jsonb); Type: COMMENT; Schema: content_management; Owner: postgres
--

COMMENT ON FUNCTION content_management.check_pattern_rule(p_text text, p_config jsonb) IS 'Verifica si un texto coincide con un patrón regex definido en la configuración';


--
-- Name: trg_auto_moderate(); Type: FUNCTION; Schema: content_management; Owner: postgres
--

CREATE FUNCTION content_management.trg_auto_moderate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result RECORD;
    v_any_match BOOLEAN := false;
    v_content_text TEXT;
    v_entity_type VARCHAR;
BEGIN
    -- Determinar qué campo contiene el texto a moderar
    -- Esto es flexible para adaptarse a diferentes tablas
    v_content_text := COALESCE(
        NEW.content_text,  -- Para tablas con campo content_text
        NEW.message,       -- Para tablas de mensajes
        NEW.comment_text,  -- Para tablas de comentarios
        NEW.body,          -- Para tablas con campo body
        NEW.text           -- Para tablas con campo text
    );

    -- Si no hay texto, no moderar
    IF v_content_text IS NULL OR v_content_text = '' THEN
        RETURN NEW;
    END IF;

    -- Determinar entity type (usar argumento del trigger o table name)
    v_entity_type := COALESCE(TG_ARGV[0]::VARCHAR, 'content');

    -- Aplicar reglas de moderación
    FOR v_result IN
        SELECT *
        FROM content_management.apply_moderation_rules(
            NEW.id,
            v_content_text,
            v_entity_type
        )
        WHERE rule_matched = true
    LOOP
        v_any_match := true;

        -- Log en audit (si existe la tabla)
        BEGIN
            INSERT INTO audit_logging.audit_logs (
                action,
                table_name,
                record_id,
                metadata,
                created_at
            ) VALUES (
                'auto_moderation',
                TG_TABLE_NAME,
                NEW.id,
                jsonb_build_object(
                    'rule_id', v_result.rule_id,
                    'rule_name', v_result.rule_name,
                    'action', v_result.action,
                    'severity', v_result.severity,
                    'auto_executed', v_result.auto_executed
                ),
                gamilit.now_mexico()
            );
        EXCEPTION
            WHEN undefined_table THEN
                -- Si la tabla audit_logs no existe, continuar
                NULL;
            WHEN OTHERS THEN
                -- Otros errores, log warning pero continuar
                RAISE WARNING 'Error logging auto-moderation: %', SQLERRM;
        END;
    END LOOP;

    -- Si la tabla tiene campo auto_moderated, marcarlo
    IF v_any_match THEN
        BEGIN
            -- Intentar setear el campo auto_moderated
            NEW.auto_moderated := true;
        EXCEPTION
            WHEN undefined_column THEN
                -- Si no existe el campo, continuar
                NULL;
        END;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION content_management.trg_auto_moderate() OWNER TO postgres;

--
-- Name: FUNCTION trg_auto_moderate(); Type: COMMENT; Schema: content_management; Owner: postgres
--

COMMENT ON FUNCTION content_management.trg_auto_moderate() IS 'Función de trigger que aplica reglas de moderación automáticamente al insertar/actualizar contenido';


--
-- Name: _validate_single_fragment(jsonb, integer, integer, integer, text, integer); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content._validate_single_fragment(p_keywords jsonb, p_min_keywords integer, p_min_length integer, p_max_length integer, p_user_text text, p_points integer) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_keyword TEXT;
    v_normalized_user_text TEXT;
    v_normalized_keyword TEXT;
    v_matched_keywords TEXT[] := ARRAY[]::TEXT[];
    v_keyword_count INTEGER := 0;
    v_text_length INTEGER;
    v_is_valid BOOLEAN := false;
    v_feedback TEXT[];
BEGIN
    -- 1. Validar longitud del texto
    v_text_length := LENGTH(TRIM(p_user_text));

    IF v_text_length < p_min_length THEN
        RETURN jsonb_build_object(
            'is_valid', false,
            'matched_keywords', '[]'::jsonb,
            'keyword_count', 0,
            'points', 0,
            'feedback', format('El texto es demasiado corto. Mínimo %s caracteres, tienes %s.',
                p_min_length, v_text_length)
        );
    END IF;

    IF v_text_length > p_max_length THEN
        RETURN jsonb_build_object(
            'is_valid', false,
            'matched_keywords', '[]'::jsonb,
            'keyword_count', 0,
            'points', 0,
            'feedback', format('El texto es demasiado largo. Máximo %s caracteres, tienes %s.',
                p_max_length, v_text_length)
        );
    END IF;

    -- 2. Normalizar texto del usuario (lowercase + quitar acentos)
    v_normalized_user_text := LOWER(gamilit.normalize_text(TRIM(p_user_text)));

    -- 3. Contar keywords que aparecen en el texto
    FOR v_keyword IN SELECT jsonb_array_elements_text(p_keywords)
    LOOP
        v_normalized_keyword := LOWER(gamilit.normalize_text(v_keyword));

        IF v_normalized_user_text LIKE '%' || v_normalized_keyword || '%' THEN
            v_matched_keywords := array_append(v_matched_keywords, v_keyword);
            v_keyword_count := v_keyword_count + 1;
        END IF;
    END LOOP;

    -- 4. Validar cantidad mínima de keywords
    v_is_valid := (v_keyword_count >= p_min_keywords);

    -- 5. Generar feedback
    v_feedback := ARRAY[]::TEXT[];

    IF v_is_valid THEN
        v_feedback := array_append(v_feedback,
            format('¡Excelente! Has incluido %s conceptos clave del fragmento.', v_keyword_count));
    ELSE
        v_feedback := array_append(v_feedback,
            format('Tu inferencia necesita más relación con el texto. Has incluido %s conceptos clave, pero necesitas al menos %s.',
                v_keyword_count, p_min_keywords));
    END IF;

    -- 6. Construir resultado
    RETURN jsonb_build_object(
        'is_valid', v_is_valid,
        'matched_keywords', to_jsonb(v_matched_keywords),
        'keyword_count', v_keyword_count,
        'min_keywords_required', p_min_keywords,
        'points', CASE WHEN v_is_valid THEN p_points ELSE 0 END,
        'max_points', p_points,
        'text_length', v_text_length,
        'min_length', p_min_length,
        'max_length', p_max_length,
        'feedback', array_to_string(v_feedback, ' ')
    );
END;
$$;


