--
-- Name: recalculate_exercise(uuid, uuid, text); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.recalculate_exercise(p_original_audit_id uuid, p_recalculated_by uuid, p_recalculation_reason text, OUT new_audit_id uuid, OUT original_score integer, OUT new_score integer, OUT has_discrepancy boolean, OUT discrepancy_details jsonb) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_original_audit RECORD;
    v_validation_result RECORD;
    v_exercise_id UUID;
    v_user_id UUID;
    v_submitted_answer JSONB;
    v_exercise_snapshot JSONB;
    v_config_snapshot JSONB;
    v_validation_duration_ms INTEGER;
    v_validation_start TIMESTAMP WITH TIME ZONE;
    v_validation_end TIMESTAMP WITH TIME ZONE;
    v_discrepancy_type TEXT;
BEGIN
    -- ========================================================================
    -- 1. RECUPERAR REGISTRO DE AUDITORÍA ORIGINAL
    -- ========================================================================
    SELECT *
    INTO v_original_audit
    FROM educational_content.exercise_validation_audits
    WHERE id = p_original_audit_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Audit record not found: %', p_original_audit_id;
    END IF;

    IF v_original_audit.is_recalculated = true THEN
        RAISE EXCEPTION 'Audit record % is already a recalculation. Use the original_audit_id instead.',
            p_original_audit_id;
    END IF;

    -- Extraer datos necesarios
    v_exercise_id := v_original_audit.exercise_id;
    v_user_id := v_original_audit.user_id;
    v_submitted_answer := v_original_audit.submitted_answer;
    v_exercise_snapshot := v_original_audit.exercise_snapshot;
    v_config_snapshot := v_original_audit.validation_config_snapshot;
    original_score := v_original_audit.score;

    -- ========================================================================
    -- 2. RE-EJECUTAR VALIDACIÓN CON LA RESPUESTA ORIGINAL
    -- ========================================================================
    v_validation_start := clock_timestamp();

    -- NOTA: Usamos validate_answer() con el ejercicio ACTUAL, no el snapshot
    -- Si se requiere validar con el snapshot exacto, necesitaríamos una función diferente
    SELECT * INTO v_validation_result
    FROM educational_content.validate_answer(
        v_exercise_id,
        v_submitted_answer
    );

    v_validation_end := clock_timestamp();
    v_validation_duration_ms := EXTRACT(MILLISECONDS FROM (v_validation_end - v_validation_start))::INTEGER;

    new_score := v_validation_result.score;

    -- ========================================================================
    -- 3. DETECTAR DISCREPANCIAS
    -- ========================================================================
    has_discrepancy := false;
    v_discrepancy_type := NULL;

    IF v_original_audit.is_correct != v_validation_result.is_correct THEN
        has_discrepancy := true;
        v_discrepancy_type := 'correctness_changed';
    ELSIF v_original_audit.score != v_validation_result.score THEN
        has_discrepancy := true;
        v_discrepancy_type := 'score_changed';
    END IF;

    discrepancy_details := jsonb_build_object(
        'original_is_correct', v_original_audit.is_correct,
        'new_is_correct', v_validation_result.is_correct,
        'original_score', v_original_audit.score,
        'new_score', v_validation_result.score,
        'score_difference', v_validation_result.score - v_original_audit.score,
        'original_feedback', v_original_audit.feedback,
        'new_feedback', v_validation_result.feedback
    );

    -- ========================================================================
    -- 4. CREAR NUEVO REGISTRO DE AUDITORÍA (RECÁLCULO)
    -- ========================================================================
    INSERT INTO educational_content.exercise_validation_audits (
        exercise_id,
        user_id,
        attempt_number,
        submitted_answer,
        submitted_at,
        exercise_snapshot,
        validation_config_snapshot,
        is_correct,
        score,
        max_score,
        feedback,
        validation_details,
        validation_function_used,
        validation_timestamp,
        validation_duration_ms,
        is_recalculated,
        recalculated_at,
        recalculated_by,
        recalculation_reason,
        original_audit_id,
        has_discrepancy,
        discrepancy_type,
        discrepancy_notes,
        client_metadata
    )
    VALUES (
        v_exercise_id,
        v_user_id,
        v_original_audit.attempt_number,
        v_submitted_answer,
        v_original_audit.submitted_at,  -- Mantener timestamp original
        v_exercise_snapshot,
        v_config_snapshot,
        v_validation_result.is_correct,
        v_validation_result.score,
        v_validation_result.max_score,
        v_validation_result.feedback,
        v_validation_result.details,
        v_original_audit.validation_function_used,
        gamilit.now_mexico(),  -- Timestamp del recálculo
        v_validation_duration_ms,
        true,  -- es recálculo
        gamilit.now_mexico(),
        p_recalculated_by,
        p_recalculation_reason,
        p_original_audit_id,
        has_discrepancy,
        v_discrepancy_type,
        CASE
            WHEN has_discrepancy THEN
                format('Recálculo encontró diferencias: %s cambió de %s a %s',
                       v_discrepancy_type,
                       v_original_audit.score,
                       v_validation_result.score)
            ELSE 'Recálculo confirmó resultado original'
        END,
        '{"source": "recalculation"}'::jsonb
    )
    RETURNING id INTO new_audit_id;

    -- ========================================================================
    -- 5. SI HAY DISCREPANCIA, MARCAR EL REGISTRO ORIGINAL
    -- ========================================================================
    IF has_discrepancy THEN
        UPDATE educational_content.exercise_validation_audits
        SET
            has_discrepancy = true,
            discrepancy_type = v_discrepancy_type,
            discrepancy_notes = format('Discrepancia detectada en recálculo %s: score cambió de %s a %s',
                                      new_audit_id,
                                      original_score,
                                      new_score),
            updated_at = gamilit.now_mexico()
        WHERE id = p_original_audit_id;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error recalculating exercise: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
END;
$$;


ALTER FUNCTION educational_content.recalculate_exercise(p_original_audit_id uuid, p_recalculated_by uuid, p_recalculation_reason text, OUT new_audit_id uuid, OUT original_score integer, OUT new_score integer, OUT has_discrepancy boolean, OUT discrepancy_details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION recalculate_exercise(p_original_audit_id uuid, p_recalculated_by uuid, p_recalculation_reason text, OUT new_audit_id uuid, OUT original_score integer, OUT new_score integer, OUT has_discrepancy boolean, OUT discrepancy_details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.recalculate_exercise(p_original_audit_id uuid, p_recalculated_by uuid, p_recalculation_reason text, OUT new_audit_id uuid, OUT original_score integer, OUT new_score integer, OUT has_discrepancy boolean, OUT discrepancy_details jsonb) IS 'Recalcula la validación de un ejercicio basado en su audit_id original.
Usa la misma respuesta enviada por el usuario (snapshot inmutable).
Crea nuevo registro de auditoría marcado como recálculo.
Si hay discrepancia (score o correctness cambió), marca ambos registros.
Útil para verificar si hubo errores en la validación original.';


--
-- Name: update_assignment_students_timestamp(); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.update_assignment_students_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = gamilit.now_mexico();

    -- Auto-calculate percentage when score is updated
    IF NEW.score IS NOT NULL AND NEW.max_score IS NOT NULL AND NEW.max_score > 0 THEN
        NEW.percentage = (NEW.score / NEW.max_score) * 100;
    END IF;

    -- Auto-set graded_at when status changes to 'graded'
    IF NEW.status = 'graded' AND OLD.status != 'graded' THEN
        NEW.graded_at = gamilit.now_mexico();
    END IF;

    -- Auto-detect late submission
    IF NEW.submitted_at IS NOT NULL THEN
        DECLARE
            assignment_due_date TIMESTAMPTZ;
        BEGIN
            SELECT due_date INTO assignment_due_date
            FROM educational_content.assignments
            WHERE id = NEW.assignment_id;

            IF assignment_due_date IS NOT NULL AND NEW.submitted_at > assignment_due_date THEN
                NEW.is_late = TRUE;
            END IF;
        END;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION educational_content.update_assignment_students_timestamp() OWNER TO postgres;

--
-- Name: update_teacher_contents_timestamp(); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.update_teacher_contents_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();

    -- Auto-set published_at when status changes to published
    IF NEW.status = 'published' AND OLD.status != 'published' THEN
        NEW.published_at = NOW();
    END IF;

    -- Increment times_assigned when target_classrooms changes
    IF NEW.target_classrooms IS DISTINCT FROM OLD.target_classrooms THEN
        NEW.times_assigned = COALESCE(OLD.times_assigned, 0) +
            (jsonb_array_length(NEW.target_classrooms) - jsonb_array_length(COALESCE(OLD.target_classrooms, '[]'::jsonb)));
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION educational_content.update_teacher_contents_timestamp() OWNER TO postgres;

--
-- Name: validate_analisis_fuentes(jsonb, jsonb, integer, boolean); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_analisis_fuentes(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean DEFAULT true, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_correct_answers JSONB;
    v_submitted_questions JSONB;
    v_total_questions INTEGER;
    v_correct_questions INTEGER := 0;
    v_question_id TEXT;
    v_results JSONB := '[]'::jsonb;
    v_critical_questions_correct INTEGER := 0;
    v_critical_questions_total INTEGER := 0;
    v_is_critical BOOLEAN;
BEGIN
    -- Formato: {\"correctAnswers\": {\"q1\": \"option_a\", \"q2\": \"option_b\", ...}}
    -- Submitted: {\"questions\": {\"q1\": \"option_a\", \"q2\": \"option_c\", ...}}
    v_correct_answers := p_solution->'correctAnswers';
    v_submitted_questions := p_submitted_answer->'questions';

    IF v_correct_answers IS NULL OR v_submitted_questions IS NULL THEN
        RAISE EXCEPTION 'Invalid analisis fuentes format';
    END IF;

    v_total_questions := COALESCE(
        (p_solution->>'totalQuestions')::integer,
        (SELECT COUNT(*) FROM jsonb_object_keys(v_correct_answers))
    );

    -- Validar cada pregunta
    FOR v_question_id IN SELECT jsonb_object_keys(v_correct_answers)
    LOOP
        -- Verificar si es pregunta crítica (identificación de sesgo, credibilidad)
        v_is_critical := COALESCE(
            (p_solution->'criticalQuestions'->v_question_id)::boolean,
            false
        );

        IF v_is_critical THEN
            v_critical_questions_total := v_critical_questions_total + 1;
        END IF;

        IF (v_correct_answers->>v_question_id) = (v_submitted_questions->>v_question_id) THEN
            v_correct_questions := v_correct_questions + 1;

            IF v_is_critical THEN
                v_critical_questions_correct := v_critical_questions_correct + 1;
            END IF;

            v_results := v_results || jsonb_build_object(
                'question_id', v_question_id,
                'is_correct', true,
                'is_critical', v_is_critical
            );
        ELSE
            v_results := v_results || jsonb_build_object(
                'question_id', v_question_id,
                'is_correct', false,
                'is_critical', v_is_critical,
                'submitted', v_submitted_questions->>v_question_id,
                'expected', v_correct_answers->>v_question_id
            );
        END IF;
    END LOOP;

    -- Calcular resultado
    is_correct := (v_correct_questions = v_total_questions);

    IF p_allow_partial_credit THEN
        score := ROUND((v_correct_questions::NUMERIC / v_total_questions) * p_max_points);

        -- Bonus por preguntas críticas correctas
        IF v_critical_questions_total > 0 AND v_critical_questions_correct = v_critical_questions_total THEN
            score := LEAST(score + 5, p_max_points);
        END IF;
    ELSE
        score := CASE WHEN is_correct THEN p_max_points ELSE 0 END;
    END IF;

    -- Feedback
    IF is_correct THEN
        feedback := format('¡Excelente análisis! Todas las %s evaluaciones de fuentes correctas.', v_total_questions);
    ELSIF v_critical_questions_total > 0 THEN
        feedback := format('Tienes %s/%s análisis correctos (%s%%). Preguntas críticas: %s/%s.',
                          v_correct_questions, v_total_questions,
                          ROUND((v_correct_questions::NUMERIC / v_total_questions) * 100),
                          v_critical_questions_correct, v_critical_questions_total);
    ELSE
        feedback := format('Tienes %s/%s análisis correctos (%s%%).',
                          v_correct_questions, v_total_questions,
                          ROUND((v_correct_questions::NUMERIC / v_total_questions) * 100));
    END IF;

    -- Details
    details := jsonb_build_object(
        'total_questions', v_total_questions,
        'correct_questions', v_correct_questions,
        'percentage', ROUND((v_correct_questions::NUMERIC / v_total_questions) * 100),
        'critical_questions_total', v_critical_questions_total,
        'critical_questions_correct', v_critical_questions_correct,
        'results_per_question', v_results
    );
END;
$$;


ALTER FUNCTION educational_content.validate_analisis_fuentes(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_analisis_fuentes(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_analisis_fuentes(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) IS 'Validador para análisis de fuentes (Módulo 3 - Pensamiento Crítico).
Valida respuestas de multiple choice sobre credibilidad, sesgo, y confiabilidad de fuentes.
Incluye peso especial para preguntas críticas.';


--
-- Name: validate_and_audit(uuid, uuid, jsonb, integer, jsonb); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_and_audit(p_exercise_id uuid, p_user_id uuid, p_submitted_answer jsonb, p_attempt_number integer, p_client_metadata jsonb DEFAULT '{}'::jsonb, OUT is_correct boolean, OUT score integer, OUT max_score integer, OUT feedback text, OUT details jsonb, OUT audit_id uuid) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_validation_start TIMESTAMP WITH TIME ZONE;
    v_validation_end TIMESTAMP WITH TIME ZONE;
    v_validation_duration_ms INTEGER;
    v_validation_result RECORD;
    v_exercise RECORD;
    v_config RECORD;
    v_exercise_snapshot JSONB;
    v_config_snapshot JSONB;
BEGIN
    -- Marcar inicio de validación
    v_validation_start := clock_timestamp();

    -- ========================================================================
    -- 1. RECUPERAR EJERCICIO Y CONFIGURACIÓN
    -- ========================================================================
    SELECT
        id,
        exercise_type,
        content,
        solution,
        max_points,
        auto_gradable
    INTO v_exercise
    FROM educational_content.exercises
    WHERE id = p_exercise_id
        AND is_active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Exercise not found or inactive: %', p_exercise_id;
    END IF;

    IF NOT v_exercise.auto_gradable THEN
        RAISE EXCEPTION 'Exercise % is not auto-gradable', p_exercise_id;
    END IF;

    -- Recuperar configuración de validación
    SELECT *
    INTO v_config
    FROM educational_content.exercise_validation_configs
    WHERE exercise_type = v_exercise.exercise_type;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Validation config not found for exercise_type: %', v_exercise.exercise_type;
    END IF;

    -- Crear snapshots para auditoría
    v_exercise_snapshot := jsonb_build_object(
        'exercise_type', v_exercise.exercise_type::text,
        'content', v_exercise.content,
        'solution', v_exercise.solution,
        'max_points', v_exercise.max_points
    );

    v_config_snapshot := jsonb_build_object(
        'validation_function', v_config.validation_function,
        'case_sensitive', v_config.case_sensitive,
        'allow_partial_credit', v_config.allow_partial_credit,
        'fuzzy_matching_threshold', v_config.fuzzy_matching_threshold,
        'normalize_text', v_config.normalize_text,
        'special_rules', v_config.special_rules,
        'default_max_points', v_config.default_max_points,
        'default_passing_score', v_config.default_passing_score
    );

    -- ========================================================================
    -- 2. EJECUTAR VALIDACIÓN
    -- ========================================================================
    SELECT * INTO v_validation_result
    FROM educational_content.validate_answer(
        p_exercise_id,
        p_submitted_answer
    );

    -- Marcar fin de validación y calcular duración
    v_validation_end := clock_timestamp();
    v_validation_duration_ms := EXTRACT(MILLISECONDS FROM (v_validation_end - v_validation_start))::INTEGER;

    -- ========================================================================
    -- 3. CREAR REGISTRO DE AUDITORÍA
    -- ========================================================================
    INSERT INTO educational_content.exercise_validation_audits (
        exercise_id,
        user_id,
        attempt_number,
        submitted_answer,
        submitted_at,
        exercise_snapshot,
        validation_config_snapshot,
        is_correct,
        score,
        max_score,
        feedback,
        validation_details,
        validation_function_used,
        validation_timestamp,
        validation_duration_ms,
        is_recalculated,
        client_metadata
    )
    VALUES (
        p_exercise_id,
        p_user_id,
        p_attempt_number,
        p_submitted_answer,
        gamilit.now_mexico(),
        v_exercise_snapshot,
        v_config_snapshot,
        v_validation_result.is_correct,
        v_validation_result.score,
        v_validation_result.max_score,
        v_validation_result.feedback,
        v_validation_result.details,
        v_config.validation_function,
        gamilit.now_mexico(),
        v_validation_duration_ms,
        false,  -- no es recálculo
        p_client_metadata
    )
    RETURNING id INTO audit_id;

    -- ========================================================================
    -- 4. RETORNAR RESULTADO DE VALIDACIÓN
    -- ========================================================================
    is_correct := v_validation_result.is_correct;
    score := v_validation_result.score;
    max_score := v_validation_result.max_score;
    feedback := v_validation_result.feedback;
    details := v_validation_result.details;

EXCEPTION
    WHEN OTHERS THEN
        -- Log error pero no fallar completamente
        RAISE WARNING 'Error in validate_and_audit for exercise %: % (SQLSTATE: %)',
            p_exercise_id, SQLERRM, SQLSTATE;

        -- Intentar crear registro de auditoría de error
        BEGIN
            INSERT INTO educational_content.exercise_validation_audits (
                exercise_id,
                user_id,
                attempt_number,
                submitted_answer,
                submitted_at,
                exercise_snapshot,
                validation_config_snapshot,
                is_correct,
                score,
                max_score,
                feedback,
                validation_details,
                validation_function_used,
                validation_timestamp,
                validation_duration_ms,
                is_recalculated,
                client_metadata
            )
            VALUES (
                p_exercise_id,
                p_user_id,
                p_attempt_number,
                p_submitted_answer,
                gamilit.now_mexico(),
                COALESCE(v_exercise_snapshot, '{}'::jsonb),
                COALESCE(v_config_snapshot, '{}'::jsonb),
                false,
                0,
                COALESCE(v_exercise.max_points, 100),
                'Error al validar la respuesta. Por favor contacte al administrador.',
                jsonb_build_object(
                    'error', SQLERRM,
                    'error_detail', SQLSTATE,
                    'exercise_id', p_exercise_id
                ),
                COALESCE(v_config.validation_function, 'unknown'),
                gamilit.now_mexico(),
                0,
                false,
                p_client_metadata
            )
            RETURNING id INTO audit_id;
        EXCEPTION
            WHEN OTHERS THEN
                -- Si incluso el audit falla, solo registrar warning
                RAISE WARNING 'Failed to create audit record for failed validation: %', SQLERRM;
        END;

        -- Retornar respuesta de error
        is_correct := false;
        score := 0;
        max_score := COALESCE(v_exercise.max_points, 100);
        feedback := 'Error al validar la respuesta. Por favor contacte al administrador.';
        details := jsonb_build_object(
            'error', SQLERRM,
            'error_detail', SQLSTATE,
            'exercise_id', p_exercise_id
        );
END;
$$;


ALTER FUNCTION educational_content.validate_and_audit(p_exercise_id uuid, p_user_id uuid, p_submitted_answer jsonb, p_attempt_number integer, p_client_metadata jsonb, OUT is_correct boolean, OUT score integer, OUT max_score integer, OUT feedback text, OUT details jsonb, OUT audit_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION validate_and_audit(p_exercise_id uuid, p_user_id uuid, p_submitted_answer jsonb, p_attempt_number integer, p_client_metadata jsonb, OUT is_correct boolean, OUT score integer, OUT max_score integer, OUT feedback text, OUT details jsonb, OUT audit_id uuid); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_and_audit(p_exercise_id uuid, p_user_id uuid, p_submitted_answer jsonb, p_attempt_number integer, p_client_metadata jsonb, OUT is_correct boolean, OUT score integer, OUT max_score integer, OUT feedback text, OUT details jsonb, OUT audit_id uuid) IS 'Función completa para validar respuesta de ejercicio Y crear registro de auditoría.
Esta debe ser la función principal llamada por el backend.
Retorna: is_correct, score, max_score, feedback, details, audit_id.
Crea snapshot inmutable de respuesta, ejercicio y configuración para trazabilidad.';


--
-- Name: validate_answer(uuid, jsonb); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_answer(p_exercise_id uuid, p_submitted_answer jsonb, OUT is_correct boolean, OUT score integer, OUT max_score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_exercise RECORD;
    v_config RECORD;
    v_result RECORD;
BEGIN
    -- ========================================================================
    -- 1. RECUPERAR EJERCICIO
    -- ========================================================================
    SELECT
        id,
        exercise_type,
        content,
        solution,
        max_points,
        auto_gradable
    INTO v_exercise
    FROM educational_content.exercises
    WHERE id = p_exercise_id
        AND is_active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Exercise not found or inactive: %', p_exercise_id;
    END IF;

    IF NOT v_exercise.auto_gradable THEN
        RAISE EXCEPTION 'Exercise % is not auto-gradable', p_exercise_id;
    END IF;

    -- ========================================================================
    -- 2. RECUPERAR CONFIGURACIÓN DE VALIDACIÓN
    -- ========================================================================
    SELECT *
    INTO v_config
    FROM educational_content.exercise_validation_configs
    WHERE exercise_type = v_exercise.exercise_type;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Validation config not found for exercise_type: %', v_exercise.exercise_type;
    END IF;

    max_score := COALESCE(v_exercise.max_points, v_config.default_max_points, 100);

    -- ========================================================================
    -- 3. EJECUTAR VALIDADOR ESPECÍFICO SEGÚN TIPO
    -- ========================================================================
    CASE v_config.validation_function

        -- ====================================================================
        -- MÓDULO 1: COMPRENSIÓN LITERAL (5 validadores)
        -- ====================================================================

        WHEN 'validate_crucigrama' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_crucigrama(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.case_sensitive,
                v_config.normalize_text
            );

        WHEN 'validate_timeline' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_timeline(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.allow_partial_credit
            );

        WHEN 'validate_word_search' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_word_search(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.allow_partial_credit,
                v_config.normalize_text
            );

        WHEN 'validate_fill_in_blank' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_fill_in_blank(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.case_sensitive,
                v_config.normalize_text,
                v_config.fuzzy_matching_threshold,
                v_config.allow_partial_credit,
                v_exercise.content
            );

        WHEN 'validate_true_false' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_true_false(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.allow_partial_credit
            );

        -- ====================================================================
        -- MÓDULO 2: COMPRENSIÓN INFERENCIAL (5 validadores)
        -- ====================================================================

        WHEN 'validate_detective_textual' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_detective_textual(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.allow_partial_credit
            );

        WHEN 'validate_construccion_hipotesis' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_construccion_hipotesis(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.fuzzy_matching_threshold,
                v_config.normalize_text,
                v_config.special_rules
            );

        WHEN 'validate_prediccion_narrativa' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_prediccion_narrativa(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.fuzzy_matching_threshold,
                v_config.normalize_text,
                v_config.special_rules
            );

        WHEN 'validate_puzzle_contexto' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_puzzle_contexto(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.allow_partial_credit
            );

        WHEN 'validate_rueda_inferencias' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_rueda_inferencias(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.allow_partial_credit,
                v_config.normalize_text
            );

        -- ====================================================================
        -- MÓDULO 3: COMPRENSIÓN CRÍTICA (5 validadores)
        -- ====================================================================

        WHEN 'validate_tribunal_opiniones' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_tribunal_opiniones(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.fuzzy_matching_threshold,
                v_config.normalize_text,
                v_config.special_rules
            );

        WHEN 'validate_debate_digital' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_debate_digital(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.fuzzy_matching_threshold,
                v_config.normalize_text,
                v_config.special_rules
            );

        WHEN 'validate_analisis_fuentes' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_analisis_fuentes(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.allow_partial_credit
            );

        WHEN 'validate_podcast_argumentativo' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_podcast_argumentativo(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.special_rules
            );

        WHEN 'validate_matriz_perspectivas' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_matriz_perspectivas(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.fuzzy_matching_threshold,
                v_config.allow_partial_credit,
                v_config.special_rules
            );

        -- ====================================================================
        -- VALIDADORES ADICIONALES (Corrección de discrepancias FE-059)
        -- ====================================================================

        WHEN 'validate_detective_connections' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_detective_connections(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.allow_partial_credit
            );

        WHEN 'validate_prediction_scenarios' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_prediction_scenarios(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.allow_partial_credit
            );

        WHEN 'validate_cause_effect_matching' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_cause_effect_matching(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.allow_partial_credit
            );

        WHEN 'validate_mapa_conceptual' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_mapa_conceptual(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.case_sensitive,
                v_config.normalize_text
            );

        WHEN 'validate_emparejamiento' THEN
            SELECT * INTO v_result
            FROM educational_content.validate_emparejamiento(
                v_exercise.solution,
                p_submitted_answer,
                max_score,
                v_config.case_sensitive,
                v_config.normalize_text
            );

        -- ====================================================================
        -- VALIDADOR NO IMPLEMENTADO
        -- ====================================================================

        ELSE
            RAISE EXCEPTION 'Validation function not implemented: %', v_config.validation_function;

    END CASE;

    -- ========================================================================
    -- 4. RETORNAR RESULTADO
    -- ========================================================================
    is_correct := v_result.is_correct;
    score := v_result.score;
    feedback := v_result.feedback;
    details := v_result.details;

EXCEPTION
    WHEN OTHERS THEN
        -- Manejo de errores: retornar respuesta segura
        RAISE WARNING 'Error validating exercise %: % (SQLSTATE: %)',
            p_exercise_id, SQLERRM, SQLSTATE;

        is_correct := false;
        score := 0;
        max_score := COALESCE(max_score, 100);
        feedback := 'Error al validar la respuesta. Por favor contacte al administrador.';
        details := jsonb_build_object(
            'error', SQLERRM,
            'error_detail', SQLSTATE,
            'exercise_id', p_exercise_id
        );
END;
$$;


ALTER FUNCTION educational_content.validate_answer(p_exercise_id uuid, p_submitted_answer jsonb, OUT is_correct boolean, OUT score integer, OUT max_score integer, OUT feedback text, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_answer(p_exercise_id uuid, p_submitted_answer jsonb, OUT is_correct boolean, OUT score integer, OUT max_score integer, OUT feedback text, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_answer(p_exercise_id uuid, p_submitted_answer jsonb, OUT is_correct boolean, OUT score integer, OUT max_score integer, OUT feedback text, OUT details jsonb) IS 'Función maestra para validar respuestas de ejercicios.
Retorna: is_correct (boolean), score (integer), max_score (integer), feedback (text), details (jsonb).
Llama a validadores específicos según exercise_type.
Soporta 15 tipos de ejercicios (Módulos 1, 2, 3).';


--
-- Name: validate_cause_effect_matching(jsonb, jsonb, integer, boolean); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_cause_effect_matching(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean DEFAULT true, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_correct_causes JSONB;
    v_submitted_causes JSONB;
    v_total_causes INTEGER := 0;
    v_correct_matches INTEGER := 0;
    v_total_matches INTEGER := 0;
    v_cause_id TEXT;
    v_correct_consequences JSONB;
    v_submitted_consequences JSONB;
    v_consequence_id TEXT;
    v_is_match BOOLEAN;
    v_results JSONB := '[]'::jsonb;
    v_cause_correct_count INTEGER;
    v_cause_total_count INTEGER;
BEGIN
    -- Extraer causas y consecuencias correctas y enviadas
    -- Formato esperado: {"causes": {"c1": ["cons1", "cons2"], "c2": ["cons3"]}}
    v_correct_causes := p_solution->'causes';
    v_submitted_causes := p_submitted_answer->'causes';

    IF v_correct_causes IS NULL OR v_submitted_causes IS NULL THEN
        RAISE EXCEPTION 'Invalid cause-effect matching format: expected {"causes": {...}}';
    END IF;

    -- Iterar sobre cada causa correcta
    FOR v_cause_id, v_correct_consequences IN
        SELECT key, value
        FROM jsonb_each(v_correct_causes)
    LOOP
        v_total_causes := v_total_causes + 1;
        v_cause_correct_count := 0;
        v_cause_total_count := jsonb_array_length(v_correct_consequences);
        v_total_matches := v_total_matches + v_cause_total_count;

        -- Obtener consecuencias enviadas por el usuario para esta causa
        v_submitted_consequences := v_submitted_causes->v_cause_id;

        IF v_submitted_consequences IS NULL THEN
            -- Usuario no envió consecuencias para esta causa
            v_results := v_results || jsonb_build_object(
                'cause_id', v_cause_id,
                'is_correct', false,
                'correct_consequences_count', 0,
                'total_consequences', v_cause_total_count
            );
            CONTINUE;
        END IF;

        -- Comparar consecuencias
        FOR v_consequence_id IN SELECT jsonb_array_elements_text(v_correct_consequences)
        LOOP
            -- Verificar si esta consecuencia está en las enviadas por el usuario
            SELECT EXISTS (
                SELECT 1
                FROM jsonb_array_elements_text(v_submitted_consequences) AS submitted_cons
                WHERE submitted_cons = v_consequence_id
            ) INTO v_is_match;

            IF v_is_match THEN
                v_cause_correct_count := v_cause_correct_count + 1;
                v_correct_matches := v_correct_matches + 1;
            END IF;
        END LOOP;

        -- Agregar resultado de esta causa
        v_results := v_results || jsonb_build_object(
            'cause_id', v_cause_id,
            'is_correct', (v_cause_correct_count = v_cause_total_count),
            'correct_consequences_count', v_cause_correct_count,
            'total_consequences', v_cause_total_count
        );
    END LOOP;

    IF v_total_matches = 0 THEN
        RAISE EXCEPTION 'No cause-effect matches defined in solution';
    END IF;

    -- Calcular resultado
    is_correct := (v_correct_matches = v_total_matches);

    IF p_allow_partial_credit THEN
        score := ROUND((v_correct_matches::NUMERIC / v_total_matches) * p_max_points);
    ELSE
        score := CASE WHEN is_correct THEN p_max_points ELSE 0 END;
    END IF;

    -- Feedback
    IF is_correct THEN
        feedback := '¡Excelente! Todas las relaciones causa-efecto son correctas.';
    ELSE
        feedback := format('Tienes %s/%s relaciones correctas.',
                          v_correct_matches, v_total_matches);
    END IF;

    -- Details
    details := jsonb_build_object(
        'total_causes', v_total_causes,
        'total_matches', v_total_matches,
        'correct_matches', v_correct_matches,
        'percentage', ROUND((v_correct_matches::NUMERIC / v_total_matches) * 100),
        'results_per_cause', v_results
    );
END;
$$;


ALTER FUNCTION educational_content.validate_cause_effect_matching(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_cause_effect_matching(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_cause_effect_matching(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) IS 'Validador para ejercicios de matching causa-efecto con drag & drop.
Verifica que las consecuencias asociadas a cada causa sean correctas.
Formato: {"causes": {"c1": ["cons1", "cons2"], "c2": ["cons3"]}}';


--
-- Name: validate_construccion_hipotesis(jsonb, jsonb, integer, numeric, boolean, jsonb); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_construccion_hipotesis(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_fuzzy_threshold numeric DEFAULT 0.70, p_normalize_text boolean DEFAULT true, p_special_rules jsonb DEFAULT '{}'::jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_hypothesis TEXT;
    v_keywords JSONB;
    v_min_words INTEGER;
    v_word_count INTEGER;
    v_keywords_found INTEGER := 0;
    v_total_keywords INTEGER;
    v_keyword TEXT;
    v_normalized_hypothesis TEXT;
    v_keyword_threshold NUMERIC;
BEGIN
    -- Extraer hipótesis enviada
    v_hypothesis := p_submitted_answer->>'hypothesis';

    IF v_hypothesis IS NULL OR TRIM(v_hypothesis) = '' THEN
        is_correct := false;
        score := 0;
        feedback := 'No se proporcionó ninguna hipótesis.';
        details := jsonb_build_object('error', 'empty_hypothesis');
        RETURN;
    END IF;

    -- Extraer configuración
    v_keywords := p_solution->'keywords';
    v_min_words := COALESCE((p_solution->>'min_words')::integer, (p_special_rules->>'min_word_count')::integer, 20);
    v_keyword_threshold := COALESCE((p_special_rules->>'keywords_threshold')::numeric, 0.60);

    -- Contar palabras
    v_word_count := array_length(string_to_array(TRIM(v_hypothesis), ' '), 1);

    -- Normalizar texto
    IF p_normalize_text THEN
        v_normalized_hypothesis := LOWER(gamilit.normalize_text(v_hypothesis));
    ELSE
        v_normalized_hypothesis := LOWER(v_hypothesis);
    END IF;

    -- Contar keywords encontradas
    IF v_keywords IS NOT NULL THEN
        v_total_keywords := jsonb_array_length(v_keywords);

        FOR v_keyword IN SELECT jsonb_array_elements_text(v_keywords)
        LOOP
            IF p_normalize_text THEN
                v_keyword := LOWER(gamilit.normalize_text(v_keyword));
            ELSE
                v_keyword := LOWER(v_keyword);
            END IF;

            IF v_normalized_hypothesis LIKE '%' || v_keyword || '%' THEN
                v_keywords_found := v_keywords_found + 1;
            END IF;
        END LOOP;
    ELSE
        v_total_keywords := 0;
    END IF;

    -- Calcular score heurístico
    -- 50% por longitud mínima + 50% por keywords
    IF v_word_count >= v_min_words THEN
        score := p_max_points / 2;
    ELSE
        score := ROUND((v_word_count::NUMERIC / v_min_words) * (p_max_points / 2));
    END IF;

    IF v_total_keywords > 0 THEN
        IF (v_keywords_found::NUMERIC / v_total_keywords) >= v_keyword_threshold THEN
            score := score + (p_max_points / 2);
        ELSE
            score := score + ROUND((v_keywords_found::NUMERIC / v_total_keywords) * (p_max_points / 2));
        END IF;
    END IF;

    is_correct := (score >= (p_max_points * 0.70));

    -- Feedback
    IF is_correct THEN
        feedback := format('Buena hipótesis. Longitud: %s palabras. Keywords encontradas: %s/%s.',
                          v_word_count, v_keywords_found, v_total_keywords);
    ELSE
        feedback := format('Hipótesis incompleta. Necesitas al menos %s palabras (tienes %s) y más keywords clave.',
                          v_min_words, v_word_count);
    END IF;

    -- Details
    details := jsonb_build_object(
        'word_count', v_word_count,
        'min_words_required', v_min_words,
        'keywords_found', v_keywords_found,
        'total_keywords', v_total_keywords,
        'validation_type', 'heuristic'
    );
END;
$$;


ALTER FUNCTION educational_content.validate_construccion_hipotesis(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_fuzzy_threshold numeric, p_normalize_text boolean, p_special_rules jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_construccion_hipotesis(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_fuzzy_threshold numeric, p_normalize_text boolean, p_special_rules jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_construccion_hipotesis(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_fuzzy_threshold numeric, p_normalize_text boolean, p_special_rules jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) IS 'Validador heurístico para construcción de hipótesis (Módulo 2).
Verifica longitud mínima y presencia de palabras clave.
NO valida calidad real del contenido - solo criterios básicos.';


--
-- Name: validate_crucigrama(jsonb, jsonb, integer, boolean, boolean); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_crucigrama(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean DEFAULT false, p_normalize_text boolean DEFAULT true, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_total_words INTEGER := 0;
    v_correct_words INTEGER := 0;
    v_word_id TEXT;
    v_correct_answer TEXT;
    v_submitted_answer TEXT;
    v_results JSONB := '[]'::jsonb;
    v_solution_clues JSONB;
    v_submitted_clues JSONB;
BEGIN
    -- ========================================================================
    -- 1. EXTRAER CLUES DE ESTRUCTURA JSONB
    -- ========================================================================
    -- Formato esperado:
    -- solution: {"clues": {"h1": "SORBONA", "h2": "NOBEL", "v1": "POLONIO"}}
    -- submitted: {"clues": {"h1": "sorbona", "h2": "nobel", "v1": "polonio"}}

    v_solution_clues := p_solution->'clues';
    v_submitted_clues := p_submitted_answer->'clues';

    IF v_solution_clues IS NULL THEN
        RAISE EXCEPTION 'Invalid solution format: missing "clues" key';
    END IF;

    IF v_submitted_clues IS NULL THEN
        RAISE EXCEPTION 'Invalid submitted answer format: missing "clues" key';
    END IF;

    -- ========================================================================
    -- 2. ITERAR SOBRE CADA CLUE Y COMPARAR
    -- ========================================================================
    FOR v_word_id IN SELECT jsonb_object_keys(v_solution_clues)
    LOOP
        v_total_words := v_total_words + 1;

        -- Obtener respuestas
        v_correct_answer := v_solution_clues->>v_word_id;
        v_submitted_answer := v_submitted_clues->>v_word_id;

        -- Normalizar si es necesario
        IF p_normalize_text THEN
            v_correct_answer := gamilit.normalize_text(v_correct_answer);
            v_submitted_answer := gamilit.normalize_text(COALESCE(v_submitted_answer, ''));
        END IF;

        -- Case-sensitive?
        IF NOT p_case_sensitive THEN
            v_correct_answer := UPPER(TRIM(v_correct_answer));
            v_submitted_answer := UPPER(TRIM(v_submitted_answer));
        ELSE
            v_correct_answer := TRIM(v_correct_answer);
            v_submitted_answer := TRIM(v_submitted_answer);
        END IF;

        -- Comparar
        IF v_submitted_answer = v_correct_answer THEN
            v_correct_words := v_correct_words + 1;

            v_results := v_results || jsonb_build_object(
                'clue_id', v_word_id,
                'is_correct', true,
                'submitted', p_submitted_answer->'clues'->>v_word_id,
                'expected', p_solution->'clues'->>v_word_id
            );
        ELSE
            v_results := v_results || jsonb_build_object(
                'clue_id', v_word_id,
                'is_correct', false,
                'submitted', COALESCE(p_submitted_answer->'clues'->>v_word_id, ''),
                'expected', p_solution->'clues'->>v_word_id
            );
        END IF;
    END LOOP;

    -- ========================================================================
    -- 3. CALCULAR SCORE Y RESULTADO
    -- ========================================================================
    IF v_total_words = 0 THEN
        RAISE EXCEPTION 'Crucigrama has no clues defined';
    END IF;

    is_correct := (v_correct_words = v_total_words);
    score := ROUND((v_correct_words::NUMERIC / v_total_words) * p_max_points);

    -- ========================================================================
    -- 4. GENERAR FEEDBACK
    -- ========================================================================
    IF is_correct THEN
        feedback := format('¡Perfecto! Todas las %s palabras están correctas.', v_total_words);
    ELSIF v_correct_words = 0 THEN
        feedback := format('Ninguna palabra correcta. Intenta de nuevo.');
    ELSE
        feedback := format('Tienes %s/%s palabras correctas (%s%%).',
                          v_correct_words,
                          v_total_words,
                          ROUND((v_correct_words::NUMERIC / v_total_words) * 100));
    END IF;

    -- ========================================================================
    -- 5. CONSTRUIR DETAILS
    -- ========================================================================
    details := jsonb_build_object(
        'total_words', v_total_words,
        'correct_words', v_correct_words,
        'incorrect_words', v_total_words - v_correct_words,
        'percentage', ROUND((v_correct_words::NUMERIC / v_total_words) * 100),
        'results_per_word', v_results
    );

END;
$$;


ALTER FUNCTION educational_content.validate_crucigrama(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_crucigrama(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_crucigrama(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) IS 'Validador para ejercicios tipo crucigrama.
Compara cada respuesta (clue) con la solución esperada.
Soporta normalización de texto y case-insensitive matching.
Retorna puntuación parcial basada en palabras correctas.';


--
-- Name: validate_debate_digital(jsonb, jsonb, integer, numeric, boolean, jsonb); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_debate_digital(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_fuzzy_threshold numeric DEFAULT 0.70, p_normalize_text boolean DEFAULT true, p_special_rules jsonb DEFAULT '{}'::jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_argument TEXT;
    v_counterargument TEXT;
    v_keywords JSONB;
    v_min_words INTEGER;
    v_total_word_count INTEGER;
    v_argument_word_count INTEGER;
    v_counterargument_word_count INTEGER;
    v_keywords_found INTEGER := 0;
    v_total_keywords INTEGER;
    v_keyword TEXT;
    v_normalized_text TEXT;
    v_keyword_threshold NUMERIC;
    v_structure_bonus INTEGER := 0;
    v_has_both_parts BOOLEAN := false;
BEGIN
    -- Extraer argumento y contraargumento enviados
    v_argument := p_submitted_answer->>'argument';
    v_counterargument := p_submitted_answer->>'counterargument';

    IF (v_argument IS NULL OR TRIM(v_argument) = '')
       AND (v_counterargument IS NULL OR TRIM(v_counterargument) = '') THEN
        is_correct := false;
        score := 0;
        feedback := 'No se proporcionó ningún argumento para el debate.';
        details := jsonb_build_object('error', 'empty_debate');
        RETURN;
    END IF;

    -- Extraer configuración (mínimo 150 palabras para debates)
    v_keywords := p_solution->'keywords';
    v_min_words := COALESCE((p_solution->>'min_words')::integer, (p_special_rules->>'min_word_count')::integer, 150);
    v_keyword_threshold := COALESCE((p_special_rules->>'keywords_threshold')::numeric, 0.60);

    -- Contar palabras en argumento
    v_argument_word_count := CASE
        WHEN v_argument IS NOT NULL AND TRIM(v_argument) != ''
        THEN array_length(string_to_array(TRIM(v_argument), ' '), 1)
        ELSE 0
    END;

    -- Contar palabras en contraargumento
    v_counterargument_word_count := CASE
        WHEN v_counterargument IS NOT NULL AND TRIM(v_counterargument) != ''
        THEN array_length(string_to_array(TRIM(v_counterargument), ' '), 1)
        ELSE 0
    END;

    v_total_word_count := v_argument_word_count + v_counterargument_word_count;
    v_has_both_parts := (v_argument_word_count > 0 AND v_counterargument_word_count > 0);

    -- Normalizar texto para búsqueda de keywords
    IF p_normalize_text THEN
        v_normalized_text := LOWER(gamilit.normalize_text(COALESCE(v_argument, '') || ' ' || COALESCE(v_counterargument, '')));
    ELSE
        v_normalized_text := LOWER(COALESCE(v_argument, '') || ' ' || COALESCE(v_counterargument, ''));
    END IF;

    -- Contar keywords encontradas
    IF v_keywords IS NOT NULL THEN
        v_total_keywords := jsonb_array_length(v_keywords);

        FOR v_keyword IN SELECT jsonb_array_elements_text(v_keywords)
        LOOP
            IF p_normalize_text THEN
                v_keyword := LOWER(gamilit.normalize_text(v_keyword));
            ELSE
                v_keyword := LOWER(v_keyword);
            END IF;

            IF v_normalized_text LIKE '%' || v_keyword || '%' THEN
                v_keywords_found := v_keywords_found + 1;
            END IF;
        END LOOP;
    ELSE
        v_total_keywords := 0;
    END IF;

    -- Bonus por estructura de debate (si tiene ambas partes)
    IF v_has_both_parts THEN
        v_structure_bonus := 10;
    END IF;

    -- Bonus adicional por palabras de refutación
    IF v_normalized_text LIKE '%sin embargo%'
       OR v_normalized_text LIKE '%por el contrario%'
       OR v_normalized_text LIKE '%aunque%'
       OR v_normalized_text LIKE '%no obstante%'
       OR v_normalized_text LIKE '%en cambio%' THEN
        v_structure_bonus := v_structure_bonus + 5;
    END IF;

    -- Calcular score heurístico
    -- 40% por longitud mínima + 40% por keywords + hasta 20% bonus estructura
    IF v_total_word_count >= v_min_words THEN
        score := ROUND(p_max_points * 0.40);
    ELSE
        score := ROUND((v_total_word_count::NUMERIC / v_min_words) * (p_max_points * 0.40));
    END IF;

    IF v_total_keywords > 0 THEN
        IF (v_keywords_found::NUMERIC / v_total_keywords) >= v_keyword_threshold THEN
            score := score + ROUND(p_max_points * 0.40);
        ELSE
            score := score + ROUND((v_keywords_found::NUMERIC / v_total_keywords) * (p_max_points * 0.40));
        END IF;
    END IF;

    -- Agregar bonus por estructura
    score := LEAST(score + v_structure_bonus, p_max_points);

    is_correct := (score >= (p_max_points * 0.70));

    -- Feedback
    IF is_correct THEN
        feedback := format('Excelente debate. Total: %s palabras. Keywords: %s/%s. Estructura completa: %s.',
                          v_total_word_count, v_keywords_found, v_total_keywords,
                          CASE WHEN v_has_both_parts THEN 'Sí' ELSE 'No' END);
    ELSE
        feedback := format('Debate incompleto. Necesitas al menos %s palabras (tienes %s)%s.',
                          v_min_words, v_total_word_count,
                          CASE WHEN NOT v_has_both_parts THEN ' y ambas partes (argumento y contraargumento)' ELSE '' END);
    END IF;

    -- Details
    details := jsonb_build_object(
        'total_word_count', v_total_word_count,
        'argument_word_count', v_argument_word_count,
        'counterargument_word_count', v_counterargument_word_count,
        'min_words_required', v_min_words,
        'keywords_found', v_keywords_found,
        'total_keywords', v_total_keywords,
        'has_both_parts', v_has_both_parts,
        'structure_bonus', v_structure_bonus,
        'validation_type', 'heuristic'
    );
END;
$$;


