Valida respuestas de multiple choice basadas en inferencias del texto.';


--
-- Name: validate_emparejamiento(jsonb, jsonb, integer, boolean, boolean); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_emparejamiento(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean DEFAULT false, p_normalize_text boolean DEFAULT true, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_submitted_matches JSONB;
    v_correct_matches JSONB;
    v_correct_count INTEGER := 0;
    v_total_count INTEGER := 0;
    v_percentage INTEGER;
    v_key TEXT;
    v_submitted_value TEXT;
    v_correct_value TEXT;
    v_results JSONB := '[]'::jsonb;
BEGIN
    -- ========================================================================
    -- 1. EXTRAER MATCHES DE ESTRUCTURA JSONB
    -- ========================================================================
    -- Formato esperado:
    -- solution: {"correctMatches": {"term1": "def1", "term2": "def2"}} o {"matches": {...}}
    -- submitted: {"matches": {"term1": "def1", "term2": "def3"}}

    v_submitted_matches := COALESCE(p_submitted_answer->'matches', '{}'::jsonb);
    v_correct_matches := COALESCE(
        p_solution->'correctMatches',
        p_solution->'matches',
        '{}'::jsonb
    );

    -- Contar total de pares esperados
    SELECT COUNT(*) INTO v_total_count
    FROM jsonb_object_keys(v_correct_matches);

    -- ========================================================================
    -- 2. VALIDAR QUE EXISTAN MATCHES
    -- ========================================================================
    IF v_total_count = 0 THEN
        is_correct := true;
        score := p_max_points;
        feedback := 'No hay emparejamientos que validar';
        details := jsonb_build_object(
            'total_matches', 0,
            'correct_matches', 0,
            'incorrect_matches', 0,
            'percentage', 100,
            'results_per_match', '[]'::jsonb
        );
        RETURN;
    END IF;

    -- ========================================================================
    -- 3. ITERAR SOBRE CADA PAR Y COMPARAR
    -- ========================================================================
    FOR v_key IN SELECT * FROM jsonb_object_keys(v_correct_matches)
    LOOP
        -- Obtener valores
        v_submitted_value := v_submitted_matches->>v_key;
        v_correct_value := v_correct_matches->>v_key;

        -- Normalizar si es necesario
        IF p_normalize_text THEN
            v_submitted_value := gamilit.normalize_text(COALESCE(v_submitted_value, ''));
            v_correct_value := gamilit.normalize_text(v_correct_value);
        END IF;

        -- Case-sensitive?
        IF NOT p_case_sensitive THEN
            v_submitted_value := UPPER(TRIM(v_submitted_value));
            v_correct_value := UPPER(TRIM(v_correct_value));
        ELSE
            v_submitted_value := TRIM(v_submitted_value);
            v_correct_value := TRIM(v_correct_value);
        END IF;

        -- Comparar
        IF v_submitted_value = v_correct_value THEN
            v_correct_count := v_correct_count + 1;

            v_results := v_results || jsonb_build_object(
                'key', v_key,
                'is_correct', true,
                'submitted', p_submitted_answer->'matches'->>v_key,
                'expected', p_solution->COALESCE(
                    CASE WHEN p_solution ? 'correctMatches' THEN 'correctMatches' ELSE 'matches' END,
                    'correctMatches'
                )->>v_key
            );
        ELSE
            v_results := v_results || jsonb_build_object(
                'key', v_key,
                'is_correct', false,
                'submitted', COALESCE(p_submitted_answer->'matches'->>v_key, ''),
                'expected', p_solution->COALESCE(
                    CASE WHEN p_solution ? 'correctMatches' THEN 'correctMatches' ELSE 'matches' END,
                    'correctMatches'
                )->>v_key
            );
        END IF;
    END LOOP;

    -- ========================================================================
    -- 4. CALCULAR SCORE Y RESULTADO
    -- ========================================================================
    v_percentage := ROUND((v_correct_count::NUMERIC / v_total_count) * 100);
    score := ROUND((v_correct_count::NUMERIC / v_total_count) * p_max_points);
    is_correct := (v_percentage >= 70);  -- Passing score 70%

    -- ========================================================================
    -- 5. GENERAR FEEDBACK
    -- ========================================================================
    IF v_correct_count = v_total_count THEN
        feedback := format('¡Perfecto! Todos los %s emparejamientos están correctos.', v_total_count);
    ELSIF v_correct_count = 0 THEN
        feedback := 'Ningún emparejamiento correcto. Revisa las relaciones entre términos.';
    ELSE
        feedback := format('Tienes %s/%s emparejamientos correctos (%s%%). Algunos emparejamientos son incorrectos.',
                          v_correct_count,
                          v_total_count,
                          v_percentage);
    END IF;

    -- ========================================================================
    -- 6. CONSTRUIR DETAILS
    -- ========================================================================
    details := jsonb_build_object(
        'total_matches', v_total_count,
        'correct_matches', v_correct_count,
        'incorrect_matches', v_total_count - v_correct_count,
        'percentage', v_percentage,
        'results_per_match', v_results
    );

END;
$$;


ALTER FUNCTION educational_content.validate_emparejamiento(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_emparejamiento(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_emparejamiento(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) IS 'Validador para ejercicios tipo emparejamiento (matching).
Compara pares item-respuesta con la solución esperada.
Soporta normalización de texto y case-insensitive matching.
Retorna puntuación parcial basada en emparejamientos correctos.
Passing score: 70%';


--
-- Name: validate_exercise_structure(educational_content.exercise_mechanic, jsonb, jsonb); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_exercise_structure(p_mechanic educational_content.exercise_mechanic, p_content jsonb, p_answer_key jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    -- ========== Validación Básica ==========
    -- content y answer_key no pueden ser null o vacíos
    IF p_content IS NULL OR p_content = '{}'::JSONB THEN
        RETURN false;
    END IF;

    IF p_answer_key IS NULL OR p_answer_key = '{}'::JSONB THEN
        RETURN false;
    END IF;

    -- ========== Validaciones Específicas por Mecánica ==========
    CASE p_mechanic
        -- VOCABULARIO
        WHEN 'multiple_choice' THEN
            -- Debe tener: question, options (array >= 2), correct_answer en answer_key
            IF NOT (
                p_content ? 'question'
                AND p_content ? 'options'
                AND jsonb_array_length(p_content->'options') >= 2
                AND p_answer_key ? 'correct_answer'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'fill_in_blank' THEN
            -- Debe tener: sentence/text, blank_position o blanks (array)
            IF NOT (
                (p_content ? 'sentence' OR p_content ? 'text')
                AND (p_content ? 'blank_position' OR p_content ? 'blanks')
                AND p_answer_key ? 'correct_answer'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'matching_pairs' THEN
            -- Debe tener: pairs (array >= 2)
            IF NOT (
                p_content ? 'pairs'
                AND jsonb_array_length(p_content->'pairs') >= 2
                AND p_answer_key ? 'correct_pairs'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'flashcard' THEN
            -- Debe tener: front (pregunta) y back (respuesta) en answer_key
            IF NOT (
                p_content ? 'front'
                AND p_answer_key ? 'back'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'word_search' THEN
            -- Debe tener: grid (matriz), words_to_find (array)
            IF NOT (
                p_content ? 'grid'
                AND p_content ? 'words_to_find'
                AND jsonb_array_length(p_content->'words_to_find') >= 1
                AND p_answer_key ? 'word_positions'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'image_association' THEN
            -- Debe tener: image_url, options o labels
            IF NOT (
                p_content ? 'image_url'
                AND (p_content ? 'options' OR p_content ? 'labels')
                AND p_answer_key ? 'correct_associations'
            ) THEN
                RETURN false;
            END IF;

        -- GRAMÁTICA
        WHEN 'verb_conjugation' THEN
            -- Debe tener: verb_infinitive, tense, subject
            IF NOT (
                p_content ? 'verb_infinitive'
                AND p_content ? 'tense'
                AND p_content ? 'subject'
                AND p_answer_key ? 'correct_conjugation'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'sentence_builder' THEN
            -- Debe tener: words (array para ordenar) o fragments
            IF NOT (
                (p_content ? 'words' OR p_content ? 'fragments')
                AND p_answer_key ? 'correct_order'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'error_detection' THEN
            -- Debe tener: sentence con errores, errors en answer_key
            IF NOT (
                p_content ? 'sentence'
                AND p_answer_key ? 'errors'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'sentence_transformation' THEN
            -- Debe tener: original_sentence, transformation_type
            IF NOT (
                p_content ? 'original_sentence'
                AND p_content ? 'transformation_type'
                AND p_answer_key ? 'transformed_sentence'
            ) THEN
                RETURN false;
            END IF;

        -- LECTURA
        WHEN 'reading_comprehension' THEN
            -- Debe tener: text/passage, questions (array)
            IF NOT (
                (p_content ? 'text' OR p_content ? 'passage')
                AND p_content ? 'questions'
                AND jsonb_array_length(p_content->'questions') >= 1
                AND p_answer_key ? 'answers'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'true_or_false' THEN
            -- Debe tener: statement, correct_answer (boolean)
            IF NOT (
                p_content ? 'statement'
                AND p_answer_key ? 'correct_answer'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'inference' THEN
            -- Debe tener: text, question, possible_inferences
            IF NOT (
                p_content ? 'text'
                AND p_content ? 'question'
                AND p_answer_key ? 'correct_inference'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'sequence_ordering' THEN
            -- Debe tener: items (array para ordenar)
            IF NOT (
                p_content ? 'items'
                AND jsonb_array_length(p_content->'items') >= 2
                AND p_answer_key ? 'correct_order'
            ) THEN
                RETURN false;
            END IF;

        -- ESCRITURA
        WHEN 'free_writing' THEN
            -- Debe tener: prompt, criteria de evaluación
            IF NOT (
                p_content ? 'prompt'
                AND (p_answer_key ? 'evaluation_criteria' OR p_answer_key ? 'rubric')
            ) THEN
                RETURN false;
            END IF;

        WHEN 'sentence_completion' THEN
            -- Debe tener: incomplete_sentence, completion
            IF NOT (
                p_content ? 'incomplete_sentence'
                AND p_answer_key ? 'correct_completion'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'translation' THEN
            -- Debe tener: source_text, source_language, target_language
            IF NOT (
                p_content ? 'source_text'
                AND p_content ? 'source_language'
                AND p_content ? 'target_language'
                AND p_answer_key ? 'correct_translation'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'dictation' THEN
            -- Debe tener: audio_url, expected_text en answer_key
            IF NOT (
                p_content ? 'audio_url'
                AND p_answer_key ? 'expected_text'
            ) THEN
                RETURN false;
            END IF;

        -- AUDIO
        WHEN 'listening_comprehension' THEN
            -- Debe tener: audio_url, questions
            IF NOT (
                p_content ? 'audio_url'
                AND p_content ? 'questions'
                AND jsonb_array_length(p_content->'questions') >= 1
                AND p_answer_key ? 'answers'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'audio_matching' THEN
            -- Debe tener: audio_files (array), labels o options
            IF NOT (
                p_content ? 'audio_files'
                AND (p_content ? 'labels' OR p_content ? 'options')
                AND p_answer_key ? 'correct_matches'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'tone_recognition' THEN
            -- Debe tener: audio_url, tone_options
            IF NOT (
                p_content ? 'audio_url'
                AND p_answer_key ? 'correct_tone'
            ) THEN
                RETURN false;
            END IF;

        -- PRONUNCIACIÓN
        WHEN 'speech_recording' THEN
            -- Debe tener: text_to_read, pronunciation_reference (audio)
            IF NOT (
                p_content ? 'text_to_read'
                AND p_answer_key ? 'pronunciation_reference'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'pronunciation_comparison' THEN
            -- Debe tener: reference_audio, text
            IF NOT (
                p_content ? 'reference_audio'
                AND p_content ? 'text'
            ) THEN
                RETURN false;
            END IF;

        -- CULTURA
        WHEN 'cultural_context' THEN
            -- Debe tener: scenario o situation, questions
            IF NOT (
                (p_content ? 'scenario' OR p_content ? 'situation')
                AND p_answer_key ? 'cultural_explanation'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'historical_timeline' THEN
            -- Debe tener: events (array), period
            IF NOT (
                p_content ? 'events'
                AND jsonb_array_length(p_content->'events') >= 2
                AND p_answer_key ? 'chronological_order'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'cultural_artifact' THEN
            -- Debe tener: artifact_image/description, questions
            IF NOT (
                (p_content ? 'artifact_image' OR p_content ? 'artifact_description')
                AND p_answer_key ? 'cultural_significance'
            ) THEN
                RETURN false;
            END IF;

        WHEN 'traditional_practice' THEN
            -- Debe tener: practice_description, cultural_context
            IF NOT (
                p_content ? 'practice_description'
                AND p_answer_key ? 'correct_understanding'
            ) THEN
                RETURN false;
            END IF;

        -- Si no hay validación específica, aceptar si tiene content y answer_key
        ELSE
            RETURN true;
    END CASE;

    -- Si pasó todas las validaciones
    RETURN true;
END;
$$;


ALTER FUNCTION educational_content.validate_exercise_structure(p_mechanic educational_content.exercise_mechanic, p_content jsonb, p_answer_key jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_exercise_structure(p_mechanic educational_content.exercise_mechanic, p_content jsonb, p_answer_key jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_exercise_structure(p_mechanic educational_content.exercise_mechanic, p_content jsonb, p_answer_key jsonb) IS 'Valida estructura JSONB de ejercicios según su mecánica. Retorna false si la estructura es inválida. Documentado en ET-EDU-001.';


--
-- Name: validate_fill_in_blank(jsonb, jsonb, integer, boolean, boolean, numeric, boolean, jsonb); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_fill_in_blank(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean DEFAULT false, p_normalize_text boolean DEFAULT true, p_fuzzy_threshold numeric DEFAULT NULL::numeric, p_allow_partial_credit boolean DEFAULT true, p_content jsonb DEFAULT NULL::jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_correct_answers JSONB;
    v_submitted_blanks JSONB;
    v_content_blanks JSONB;
    v_total_blanks INTEGER;
    v_correct_blanks INTEGER := 0;
    v_blank_id TEXT;
    v_correct_answer TEXT;
    v_submitted_answer TEXT;
    v_alternatives JSONB;
    v_is_valid BOOLEAN;
    v_similarity NUMERIC;
    v_results JSONB := '[]'::jsonb;
BEGIN
    -- Extraer respuestas correctas y respuestas enviadas
    v_correct_answers := p_solution->'correctAnswers';
    v_submitted_blanks := p_submitted_answer->'blanks';

    IF v_correct_answers IS NULL OR v_submitted_blanks IS NULL THEN
        RAISE EXCEPTION 'Invalid fill-in-blank format';
    END IF;

    -- Extraer blanks del content (si está disponible)
    IF p_content IS NOT NULL THEN
        v_content_blanks := p_content->'blanks';
    END IF;

    v_total_blanks := (SELECT COUNT(*) FROM jsonb_object_keys(v_correct_answers));

    -- Validar cada blank
    FOR v_blank_id IN SELECT jsonb_object_keys(v_correct_answers)
    LOOP
        v_correct_answer := v_correct_answers->>v_blank_id;
        v_submitted_answer := v_submitted_blanks->>v_blank_id;

        -- Obtener alternativas del content->blanks si existen
        v_alternatives := NULL;
        IF v_content_blanks IS NOT NULL THEN
            -- Buscar el blank con este id en el array de blanks
            SELECT elem->'alternatives'
            INTO v_alternatives
            FROM jsonb_array_elements(v_content_blanks) AS elem
            WHERE elem->>'id' = v_blank_id
            LIMIT 1;
        END IF;

        -- Normalizar respuesta correcta
        IF p_normalize_text THEN
            v_correct_answer := gamilit.normalize_text(v_correct_answer);
            v_submitted_answer := gamilit.normalize_text(COALESCE(v_submitted_answer, ''));
        END IF;

        -- Case-sensitive?
        IF NOT p_case_sensitive THEN
            v_correct_answer := UPPER(TRIM(v_correct_answer));
            v_submitted_answer := UPPER(TRIM(v_submitted_answer));
        ELSE
            v_correct_answer := TRIM(v_correct_answer);
            v_submitted_answer := TRIM(v_submitted_answer);
        END IF;

        -- Validar contra correctAnswer O alternatives
        v_is_valid := false;

        -- 1. Validar contra correctAnswer (lógica existente)
        IF p_fuzzy_threshold IS NOT NULL THEN
            v_similarity := similarity(v_correct_answer, v_submitted_answer);
            IF v_similarity >= p_fuzzy_threshold THEN
                v_is_valid := true;
            END IF;
        ELSE
            -- Exact match con correctAnswer
            IF v_submitted_answer = v_correct_answer THEN
                v_is_valid := true;
            END IF;
        END IF;

        -- 2. Si no es válido, validar contra alternatives (si existen)
        IF NOT v_is_valid AND v_alternatives IS NOT NULL THEN
            -- Iterar sobre alternatives
            FOR i IN 0..jsonb_array_length(v_alternatives)-1
            LOOP
                DECLARE
                    v_alternative TEXT;
                BEGIN
                    v_alternative := v_alternatives->>i;

                    -- Normalizar alternativa
                    IF p_normalize_text THEN
                        v_alternative := gamilit.normalize_text(v_alternative);
                    END IF;

                    IF NOT p_case_sensitive THEN
                        v_alternative := UPPER(TRIM(v_alternative));
                    ELSE
                        v_alternative := TRIM(v_alternative);
                    END IF;

                    -- Validar contra alternativa
                    IF p_fuzzy_threshold IS NOT NULL THEN
                        v_similarity := similarity(v_alternative, v_submitted_answer);
                        IF v_similarity >= p_fuzzy_threshold THEN
                            v_is_valid := true;
                            EXIT;  -- Salir del loop si encontramos match
                        END IF;
                    ELSE
                        IF v_submitted_answer = v_alternative THEN
                            v_is_valid := true;
                            EXIT;
                        END IF;
                    END IF;
                END;
            END LOOP;
        END IF;

        -- Registrar resultado
        IF v_is_valid THEN
            v_correct_blanks := v_correct_blanks + 1;
            v_results := v_results || jsonb_build_object(
                'blank_id', v_blank_id,
                'is_correct', true,
                'similarity', CASE WHEN p_fuzzy_threshold IS NOT NULL THEN v_similarity ELSE NULL END
            );
        ELSE
            v_results := v_results || jsonb_build_object(
                'blank_id', v_blank_id,
                'is_correct', false,
                'similarity', CASE WHEN p_fuzzy_threshold IS NOT NULL THEN v_similarity ELSE NULL END
            );
        END IF;
    END LOOP;

    -- Calcular resultado
    is_correct := (v_correct_blanks = v_total_blanks);

    IF p_allow_partial_credit THEN
        score := ROUND((v_correct_blanks::NUMERIC / v_total_blanks) * p_max_points);
    ELSE
        score := CASE WHEN is_correct THEN p_max_points ELSE 0 END;
    END IF;

    -- Feedback
    IF is_correct THEN
        feedback := format('¡Excelente! Todos los %s espacios correctos.', v_total_blanks);
    ELSE
        feedback := format('Tienes %s/%s espacios correctos.',
                          v_correct_blanks, v_total_blanks);
    END IF;

    -- Details
    details := jsonb_build_object(
        'total_blanks', v_total_blanks,
        'correct_blanks', v_correct_blanks,
        'percentage', ROUND((v_correct_blanks::NUMERIC / v_total_blanks) * 100),
        'fuzzy_matching_used', (p_fuzzy_threshold IS NOT NULL),
        'results_per_blank', v_results
    );
END;
$$;


ALTER FUNCTION educational_content.validate_fill_in_blank(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, p_fuzzy_threshold numeric, p_allow_partial_credit boolean, p_content jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_fill_in_blank(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, p_fuzzy_threshold numeric, p_allow_partial_credit boolean, p_content jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_fill_in_blank(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, p_fuzzy_threshold numeric, p_allow_partial_credit boolean, p_content jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) IS 'Validador para ejercicios tipo completar espacios.
Soporta fuzzy matching con threshold configurable.
Soporta múltiples alternativas válidas por espacio en blanco (desde p_content->blanks[].alternatives).
Para ejercicios sin alternativas, valida solo contra solution->correctAnswers (compatibilidad hacia atrás).';


--
-- Name: validate_mapa_conceptual(jsonb, jsonb, integer, boolean, boolean); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_mapa_conceptual(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean DEFAULT false, p_normalize_text boolean DEFAULT true, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_submitted_connections JSONB;
    v_solution_connections JSONB;
    v_correct_count INTEGER := 0;
    v_total_count INTEGER := 0;
    v_percentage INTEGER;
    v_connection JSONB;
    v_solution_conn JSONB;
    v_from_submitted TEXT;
    v_to_submitted TEXT;
    v_from_solution TEXT;
    v_to_solution TEXT;
    v_is_match BOOLEAN;
    v_results JSONB := '[]'::jsonb;
BEGIN
    -- ========================================================================
    -- 1. EXTRAER CONEXIONES DE ESTRUCTURA JSONB
    -- ========================================================================
    -- Formato esperado:
    -- solution: {"connections": [{"from": "A", "to": "B"}, {"from": "C", "to": "D"}]}
    -- submitted: {"connections": [{"from": "A", "to": "B"}, {"from": "C", "to": "E"}]}

    v_solution_connections := COALESCE(p_solution->'connections', '[]'::jsonb);
    v_submitted_connections := COALESCE(p_submitted_answer->'connections', '[]'::jsonb);

    -- Contar total de conexiones esperadas
    v_total_count := jsonb_array_length(v_solution_connections);

    -- ========================================================================
    -- 2. VALIDAR QUE EXISTAN CONEXIONES
    -- ========================================================================
    IF v_total_count = 0 THEN
        is_correct := true;
        score := p_max_points;
        feedback := 'No hay conexiones que validar';
        details := jsonb_build_object(
            'total_connections', 0,
            'correct_connections', 0,
            'incorrect_connections', 0,
            'percentage', 100,
            'results_per_connection', '[]'::jsonb
        );
        RETURN;
    END IF;

    -- ========================================================================
    -- 3. ITERAR SOBRE CONEXIONES SUBMITTED Y COMPARAR CON SOLUTION
    -- ========================================================================
    FOR v_connection IN SELECT * FROM jsonb_array_elements(v_submitted_connections)
    LOOP
        -- Obtener valores from/to del submitted
        v_from_submitted := v_connection->>'from';
        v_to_submitted := v_connection->>'to';

        -- Normalizar si es necesario
        IF p_normalize_text THEN
            v_from_submitted := gamilit.normalize_text(COALESCE(v_from_submitted, ''));
            v_to_submitted := gamilit.normalize_text(COALESCE(v_to_submitted, ''));
        END IF;

        -- Case-sensitive?
        IF NOT p_case_sensitive THEN
            v_from_submitted := UPPER(TRIM(v_from_submitted));
            v_to_submitted := UPPER(TRIM(v_to_submitted));
        ELSE
            v_from_submitted := TRIM(v_from_submitted);
            v_to_submitted := TRIM(v_to_submitted);
        END IF;

        -- Buscar match en solution (bidireccional: from->to o to->from)
        v_is_match := false;

        FOR v_solution_conn IN SELECT * FROM jsonb_array_elements(v_solution_connections)
        LOOP
            v_from_solution := v_solution_conn->>'from';
            v_to_solution := v_solution_conn->>'to';

            -- Normalizar solution
            IF p_normalize_text THEN
                v_from_solution := gamilit.normalize_text(COALESCE(v_from_solution, ''));
                v_to_solution := gamilit.normalize_text(COALESCE(v_to_solution, ''));
            END IF;

            IF NOT p_case_sensitive THEN
                v_from_solution := UPPER(TRIM(v_from_solution));
                v_to_solution := UPPER(TRIM(v_to_solution));
            ELSE
                v_from_solution := TRIM(v_from_solution);
                v_to_solution := TRIM(v_to_solution);
            END IF;

            -- Comparar bidireccional
            IF (v_from_submitted = v_from_solution AND v_to_submitted = v_to_solution) OR
               (v_from_submitted = v_to_solution AND v_to_submitted = v_from_solution) THEN
                v_is_match := true;
                EXIT;
            END IF;
        END LOOP;

        -- Registrar resultado
        IF v_is_match THEN
            v_correct_count := v_correct_count + 1;
            v_results := v_results || jsonb_build_object(
                'from', v_connection->>'from',
                'to', v_connection->>'to',
                'is_correct', true
            );
        ELSE
            v_results := v_results || jsonb_build_object(
                'from', v_connection->>'from',
                'to', v_connection->>'to',
                'is_correct', false
            );
        END IF;
    END LOOP;

    -- ========================================================================
    -- 4. CALCULAR SCORE Y RESULTADO
    -- ========================================================================
    v_percentage := ROUND((v_correct_count::NUMERIC / v_total_count) * 100);
    score := ROUND((v_correct_count::NUMERIC / v_total_count) * p_max_points);
    is_correct := (v_percentage >= 70);  -- Passing score 70%

    -- ========================================================================
    -- 5. GENERAR FEEDBACK
    -- ========================================================================
    IF v_correct_count = v_total_count THEN
        feedback := format('¡Excelente! Todas las %s conexiones están correctas.', v_total_count);
    ELSIF v_correct_count = 0 THEN
        feedback := 'Ninguna conexión correcta. Revisa las relaciones entre conceptos.';
    ELSE
        feedback := format('Tienes %s/%s conexiones correctas (%s%%). Revisa las conexiones entre conceptos.',
                          v_correct_count,
                          v_total_count,
                          v_percentage);
    END IF;

    -- ========================================================================
    -- 6. CONSTRUIR DETAILS
    -- ========================================================================
    details := jsonb_build_object(
        'total_connections', v_total_count,
        'correct_connections', v_correct_count,
        'incorrect_connections', v_total_count - v_correct_count,
        'percentage', v_percentage,
        'results_per_connection', v_results
    );

END;
$$;


ALTER FUNCTION educational_content.validate_mapa_conceptual(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_mapa_conceptual(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_mapa_conceptual(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_case_sensitive boolean, p_normalize_text boolean, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) IS 'Validador para ejercicios tipo mapa conceptual.
Compara conexiones entre conceptos con la solución esperada.
Soporta matching bidireccional (A->B es equivalente a B->A).
Soporta normalización de texto y case-insensitive matching.
Retorna puntuación parcial basada en conexiones correctas.
Passing score: 70%';


--
-- Name: validate_matriz_perspectivas(jsonb, jsonb, integer, boolean, boolean, jsonb); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_matriz_perspectivas(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean DEFAULT true, p_normalize_text boolean DEFAULT true, p_special_rules jsonb DEFAULT '{}'::jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_required_perspectives JSONB;
    v_submitted_perspectives JSONB;
    v_total_perspectives INTEGER;
    v_completed_perspectives INTEGER := 0;
    v_perspective_id TEXT;
    v_perspective_text TEXT;
    v_min_chars_per_cell INTEGER;
    v_perspective_keywords JSONB;
    v_keywords_found INTEGER;
    v_keyword TEXT;
    v_normalized_text TEXT;
    v_char_count INTEGER;
    v_results JSONB := '[]'::jsonb;
    v_cell_valid BOOLEAN;
    v_has_keywords BOOLEAN;
BEGIN
    -- Formato: {\"requiredPerspectives\": [\"perspective1\", \"perspective2\", ...]}
    -- Submitted: {\"perspectives\": {\"perspective1\": \"text\", \"perspective2\": \"text\", ...}}
    v_required_perspectives := p_solution->'requiredPerspectives';
    v_submitted_perspectives := p_submitted_answer->'perspectives';

    IF v_required_perspectives IS NULL OR v_submitted_perspectives IS NULL THEN
        RAISE EXCEPTION 'Invalid matriz perspectivas format';
    END IF;

    v_total_perspectives := jsonb_array_length(v_required_perspectives);
    v_min_chars_per_cell := COALESCE(
        (p_solution->>'min_chars_per_cell')::integer,
        (p_special_rules->>'min_chars_per_cell')::integer,
        50  -- 50 caracteres por defecto
    );

    -- Validar cada perspectiva requerida
    FOR v_perspective_id IN SELECT jsonb_array_elements_text(v_required_perspectives)
    LOOP
        v_perspective_text := v_submitted_perspectives->>v_perspective_id;
        v_cell_valid := false;
        v_has_keywords := false;

        -- Verificar si la celda está vacía
        IF v_perspective_text IS NULL OR TRIM(v_perspective_text) = '' THEN
            v_results := v_results || jsonb_build_object(
                'perspective_id', v_perspective_id,
                'is_complete', false,
                'char_count', 0,
                'min_chars_required', v_min_chars_per_cell,
                'has_keywords', false
            );
            CONTINUE;
        END IF;

        -- Contar caracteres
        v_char_count := LENGTH(TRIM(v_perspective_text));

        -- Normalizar para búsqueda de keywords
        IF p_normalize_text THEN
            v_normalized_text := LOWER(gamilit.normalize_text(v_perspective_text));
        ELSE
            v_normalized_text := LOWER(v_perspective_text);
        END IF;

        -- Buscar keywords específicas de esta perspectiva (si existen)
        v_perspective_keywords := p_solution->'perspectiveKeywords'->v_perspective_id;
        v_keywords_found := 0;

        IF v_perspective_keywords IS NOT NULL THEN
            FOR v_keyword IN SELECT jsonb_array_elements_text(v_perspective_keywords)
            LOOP
                IF p_normalize_text THEN
                    v_keyword := LOWER(gamilit.normalize_text(v_keyword));
                ELSE
                    v_keyword := LOWER(v_keyword);
                END IF;

                IF v_normalized_text LIKE '%' || v_keyword || '%' THEN
                    v_keywords_found := v_keywords_found + 1;
                END IF;
            END LOOP;

            v_has_keywords := (v_keywords_found > 0);
        ELSE
            v_has_keywords := true;  -- No hay keywords requeridas
        END IF;

        -- Validar celda
        IF v_char_count >= v_min_chars_per_cell AND v_has_keywords THEN
            v_cell_valid := true;
            v_completed_perspectives := v_completed_perspectives + 1;
        END IF;

        -- Agregar resultado
        v_results := v_results || jsonb_build_object(
            'perspective_id', v_perspective_id,
            'is_complete', v_cell_valid,
            'char_count', v_char_count,
            'min_chars_required', v_min_chars_per_cell,
            'has_keywords', v_has_keywords,
            'keywords_found', v_keywords_found
        );
    END LOOP;

    -- Calcular resultado
    is_correct := (v_completed_perspectives = v_total_perspectives);

    IF p_allow_partial_credit THEN
        score := ROUND((v_completed_perspectives::NUMERIC / v_total_perspectives) * p_max_points);
    ELSE
        score := CASE WHEN is_correct THEN p_max_points ELSE 0 END;
    END IF;

    -- Feedback
    IF is_correct THEN
        feedback := format('¡Excelente! Matriz completa con las %s perspectivas.', v_total_perspectives);
    ELSE
        feedback := format('Matriz incompleta. Completaste %s/%s perspectivas (%s%%).',
                          v_completed_perspectives, v_total_perspectives,
                          ROUND((v_completed_perspectives::NUMERIC / v_total_perspectives) * 100));
    END IF;

    -- Details
    details := jsonb_build_object(
        'total_perspectives', v_total_perspectives,
        'completed_perspectives', v_completed_perspectives,
        'percentage', ROUND((v_completed_perspectives::NUMERIC / v_total_perspectives) * 100),
        'min_chars_per_cell', v_min_chars_per_cell,
        'results_per_perspective', v_results
    );
END;
$$;


ALTER FUNCTION educational_content.validate_matriz_perspectivas(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean, p_normalize_text boolean, p_special_rules jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_matriz_perspectivas(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean, p_normalize_text boolean, p_special_rules jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_matriz_perspectivas(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_allow_partial_credit boolean, p_normalize_text boolean, p_special_rules jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) IS 'Validador para matriz de perspectivas (Módulo 3 - Pensamiento Crítico).
Valida que todas las celdas de la matriz estén completas con texto mínimo.
Opcionalmente verifica presencia de keywords específicas por perspectiva.';


--
-- Name: validate_module4_module5_answer(educational_content.exercise_type, jsonb, integer); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_module4_module5_answer(p_exercise_type educational_content.exercise_type, p_submitted_answer jsonb, p_max_points integer DEFAULT 100, OUT is_valid boolean, OUT validation_errors text[], OUT requires_manual_review boolean, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_errors TEXT[] := ARRAY[]::TEXT[];
    v_details JSONB := '{}'::jsonb;
    v_claim JSONB;
    v_entry JSONB;
    v_panel JSONB;
    v_annotation JSONB;
    v_count INTEGER;
    i INTEGER;
BEGIN
    -- ========================================================================
    -- 1. VALIDACIÓN BÁSICA
    -- ========================================================================
    IF p_submitted_answer IS NULL OR p_submitted_answer = 'null'::jsonb THEN
        is_valid := false;
        validation_errors := ARRAY['Respuesta vacía o nula']::TEXT[];
        requires_manual_review := true;
        details := jsonb_build_object('error', 'null_answer');
        RETURN;
    END IF;

    -- ========================================================================
    -- 2. VALIDACIÓN POR TIPO DE EJERCICIO
    -- ========================================================================
    CASE p_exercise_type

        -- ====================================================================
        -- MÓDULO 4: LECTURA DIGITAL Y MULTIMODAL
        -- ====================================================================

        -- --------------------------------------------------------------------
        -- 4.1. VERIFICADOR DE FAKE NEWS
        -- --------------------------------------------------------------------
        WHEN 'verificador_fake_news' THEN
            -- Validar campo claims_verified
            IF NOT (p_submitted_answer ? 'claims_verified') THEN
                v_errors := array_append(v_errors, 'Campo "claims_verified" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'claims_verified') != 'array' THEN
                v_errors := array_append(v_errors, 'Campo "claims_verified" debe ser un array');
            ELSE
                v_count := jsonb_array_length(p_submitted_answer->'claims_verified');

                IF v_count = 0 THEN
                    v_errors := array_append(v_errors, 'El array "claims_verified" no puede estar vacío');
                ELSE
                    -- Validar estructura de cada claim
                    FOR i IN 0..v_count-1
                    LOOP
                        v_claim := p_submitted_answer->'claims_verified'->i;

                        IF NOT (v_claim ? 'claim_id') THEN
                            v_errors := array_append(v_errors, format('Claim %s: falta campo "claim_id"', i + 1));
                        END IF;

                        IF NOT (v_claim ? 'is_fake') THEN
                            v_errors := array_append(v_errors, format('Claim %s: falta campo "is_fake"', i + 1));
                        ELSIF jsonb_typeof(v_claim->'is_fake') != 'boolean' THEN
                            v_errors := array_append(v_errors, format('Claim %s: "is_fake" debe ser boolean', i + 1));
                        END IF;

                        IF NOT (v_claim ? 'evidence') THEN
                            v_errors := array_append(v_errors, format('Claim %s: falta campo "evidence"', i + 1));
                        ELSIF length(trim(v_claim->>'evidence')) < 10 THEN
                            v_errors := array_append(v_errors, format('Claim %s: "evidence" debe tener al menos 10 caracteres', i + 1));
                        END IF;
                    END LOOP;
                END IF;

                v_details := jsonb_build_object(
                    'claims_count', v_count,
                    'validation_type', 'structure'
                );
            END IF;

        -- --------------------------------------------------------------------
        -- 4.2. INFOGRAFÍA INTERACTIVA
        -- --------------------------------------------------------------------
        WHEN 'infografia_interactiva' THEN
            -- Validar campo answers
            IF NOT (p_submitted_answer ? 'answers') THEN
                v_errors := array_append(v_errors, 'Campo "answers" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'answers') != 'object' THEN
                v_errors := array_append(v_errors, 'Campo "answers" debe ser un objeto');
            END IF;

            -- Validar campo sections_explored
            IF NOT (p_submitted_answer ? 'sections_explored') THEN
                v_errors := array_append(v_errors, 'Campo "sections_explored" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'sections_explored') != 'array' THEN
                v_errors := array_append(v_errors, 'Campo "sections_explored" debe ser un array');
            ELSIF jsonb_array_length(p_submitted_answer->'sections_explored') = 0 THEN
                v_errors := array_append(v_errors, 'El array "sections_explored" debe tener al menos 1 elemento');
            END IF;

            v_details := jsonb_build_object(
                'sections_explored_count', jsonb_array_length(p_submitted_answer->'sections_explored'),
                'validation_type', 'structure'
            );

        -- --------------------------------------------------------------------
        -- 4.3. QUIZ TIKTOK
        -- --------------------------------------------------------------------
        WHEN 'quiz_tiktok' THEN
            -- Validar campo answers
            IF NOT (p_submitted_answer ? 'answers') THEN
                v_errors := array_append(v_errors, 'Campo "answers" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'answers') != 'array' THEN
                v_errors := array_append(v_errors, 'Campo "answers" debe ser un array');
            ELSE
                v_count := jsonb_array_length(p_submitted_answer->'answers');

                IF v_count = 0 THEN
                    v_errors := array_append(v_errors, 'El array "answers" no puede estar vacío');
                ELSE
                    -- Validar que cada elemento sea un número
                    FOR i IN 0..v_count-1
                    LOOP
                        IF jsonb_typeof(p_submitted_answer->'answers'->i) != 'number' THEN
                            v_errors := array_append(v_errors, format('Respuesta %s: debe ser un número', i + 1));
                        ELSIF (p_submitted_answer->'answers'->>i)::INTEGER < 0 THEN
                            v_errors := array_append(v_errors, format('Respuesta %s: debe ser >= 0', i + 1));
                        END IF;
                    END LOOP;
                END IF;

                v_details := jsonb_build_object(
                    'answers_count', v_count,
                    'validation_type', 'structure'
                );
            END IF;

        -- --------------------------------------------------------------------
        -- 4.4. NAVEGACIÓN HIPERTEXTUAL
        -- --------------------------------------------------------------------
        WHEN 'navegacion_hipertextual' THEN
            -- Validar campo path
            IF NOT (p_submitted_answer ? 'path') THEN
                v_errors := array_append(v_errors, 'Campo "path" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'path') != 'array' THEN
                v_errors := array_append(v_errors, 'Campo "path" debe ser un array');
            ELSIF jsonb_array_length(p_submitted_answer->'path') < 2 THEN
                v_errors := array_append(v_errors, 'El array "path" debe tener al menos 2 elementos (inicio y destino)');
            END IF;

            -- Validar campo information_found
            IF NOT (p_submitted_answer ? 'information_found') THEN
                v_errors := array_append(v_errors, 'Campo "information_found" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'information_found') != 'object' THEN
                v_errors := array_append(v_errors, 'Campo "information_found" debe ser un objeto');
            END IF;

            v_details := jsonb_build_object(
                'path_length', jsonb_array_length(p_submitted_answer->'path'),
                'validation_type', 'structure'
            );

        -- --------------------------------------------------------------------
        -- 4.5. ANÁLISIS DE MEMES
        -- --------------------------------------------------------------------
        WHEN 'analisis_memes' THEN
            -- Validar campo annotations
            IF NOT (p_submitted_answer ? 'annotations') THEN
                v_errors := array_append(v_errors, 'Campo "annotations" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'annotations') != 'array' THEN
                v_errors := array_append(v_errors, 'Campo "annotations" debe ser un array');
            ELSE
                v_count := jsonb_array_length(p_submitted_answer->'annotations');

                -- Validar estructura de cada anotación
                FOR i IN 0..v_count-1
                LOOP
                    v_annotation := p_submitted_answer->'annotations'->i;

                    IF NOT (v_annotation ? 'element') THEN
                        v_errors := array_append(v_errors, format('Anotación %s: falta campo "element"', i + 1));
                    END IF;

                    IF NOT (v_annotation ? 'interpretation') THEN
                        v_errors := array_append(v_errors, format('Anotación %s: falta campo "interpretation"', i + 1));
                    END IF;
                END LOOP;
            END IF;

            -- Validar campo analysis
            IF NOT (p_submitted_answer ? 'analysis') THEN
                v_errors := array_append(v_errors, 'Campo "analysis" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'analysis') != 'object' THEN
                v_errors := array_append(v_errors, 'Campo "analysis" debe ser un objeto');
            ELSE
                IF NOT (p_submitted_answer->'analysis' ? 'message') THEN
                    v_errors := array_append(v_errors, 'Campo "analysis.message" faltante');
                ELSIF length(trim(p_submitted_answer->'analysis'->>'message')) = 0 THEN
                    v_errors := array_append(v_errors, 'Campo "analysis.message" no puede estar vacío');
                END IF;
            END IF;

            v_details := jsonb_build_object(
                'annotations_count', jsonb_array_length(p_submitted_answer->'annotations'),
                'validation_type', 'structure'
            );

        -- ====================================================================
        -- MÓDULO 5: PRODUCCIÓN Y EXPRESIÓN LECTORA
        -- ====================================================================

        -- --------------------------------------------------------------------
        -- 5.1. DIARIO MULTIMEDIA
        -- --------------------------------------------------------------------
        WHEN 'diario_multimedia' THEN
            -- Validar campo entries
            IF NOT (p_submitted_answer ? 'entries') THEN
                v_errors := array_append(v_errors, 'Campo "entries" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'entries') != 'array' THEN
                v_errors := array_append(v_errors, 'Campo "entries" debe ser un array');
            ELSE
                v_count := jsonb_array_length(p_submitted_answer->'entries');

                IF v_count = 0 THEN
                    v_errors := array_append(v_errors, 'El array "entries" debe tener al menos 1 entrada');
                ELSE
                    -- Validar estructura de cada entrada
                    FOR i IN 0..v_count-1
                    LOOP
                        v_entry := p_submitted_answer->'entries'->i;

                        IF NOT (v_entry ? 'date') THEN
                            v_errors := array_append(v_errors, format('Entrada %s: falta campo "date"', i + 1));
                        END IF;

                        IF NOT (v_entry ? 'content') THEN
                            v_errors := array_append(v_errors, format('Entrada %s: falta campo "content"', i + 1));
                        ELSIF length(trim(v_entry->>'content')) < 50 THEN
                            v_errors := array_append(v_errors, format('Entrada %s: "content" debe tener al menos 50 caracteres', i + 1));
                        END IF;
                    END LOOP;
                END IF;

                v_details := jsonb_build_object(
                    'entries_count', v_count,
                    'validation_type', 'structure'
                );
            END IF;

        -- --------------------------------------------------------------------
        -- 5.2. CÓMIC DIGITAL
        -- --------------------------------------------------------------------
        WHEN 'comic_digital' THEN
            -- Validar campo panels
            IF NOT (p_submitted_answer ? 'panels') THEN
                v_errors := array_append(v_errors, 'Campo "panels" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'panels') != 'array' THEN
                v_errors := array_append(v_errors, 'Campo "panels" debe ser un array');
            ELSE
                v_count := jsonb_array_length(p_submitted_answer->'panels');

                IF v_count < 3 THEN
                    v_errors := array_append(v_errors, 'El array "panels" debe tener al menos 3 paneles');
                ELSE
                    -- Validar estructura de cada panel
                    FOR i IN 0..v_count-1
                    LOOP
                        v_panel := p_submitted_answer->'panels'->i;

                        -- Cada panel debe tener dialogue O narration (al menos uno)
                        IF NOT (v_panel ? 'dialogue') AND NOT (v_panel ? 'narration') THEN
                            v_errors := array_append(v_errors, format('Panel %s: debe tener "dialogue" o "narration"', i + 1));
                        END IF;
                    END LOOP;
                END IF;

                v_details := jsonb_build_object(
                    'panels_count', v_count,
                    'validation_type', 'structure'
                );
            END IF;

        -- --------------------------------------------------------------------
        -- 5.3. VIDEO CARTA
        -- --------------------------------------------------------------------
        WHEN 'video_carta' THEN
            -- Validar que existe video_url O script
            IF NOT (p_submitted_answer ? 'video_url') AND NOT (p_submitted_answer ? 'script') THEN
                v_errors := array_append(v_errors, 'Debe proporcionar "video_url" o "script"');
            END IF;

            -- Si existe script, validar longitud mínima
            IF (p_submitted_answer ? 'script') THEN
                IF length(trim(p_submitted_answer->>'script')) < 100 THEN
                    v_errors := array_append(v_errors, 'Campo "script" debe tener al menos 100 caracteres');
                END IF;
            END IF;

            -- Validar campo duration
            IF NOT (p_submitted_answer ? 'duration') THEN
                v_errors := array_append(v_errors, 'Campo "duration" faltante');
            ELSIF jsonb_typeof(p_submitted_answer->'duration') != 'number' THEN
                v_errors := array_append(v_errors, 'Campo "duration" debe ser un número');
            ELSIF (p_submitted_answer->>'duration')::INTEGER <= 0 THEN
                v_errors := array_append(v_errors, 'Campo "duration" debe ser mayor a 0');
            END IF;

            v_details := jsonb_build_object(
                'has_video', (p_submitted_answer ? 'video_url'),
                'has_script', (p_submitted_answer ? 'script'),
                'duration', COALESCE((p_submitted_answer->>'duration')::INTEGER, 0),
                'validation_type', 'structure'
            );

        -- ====================================================================
        -- TIPO NO SOPORTADO
        -- ====================================================================
        ELSE
            v_errors := array_append(v_errors, format('Tipo de ejercicio no soportado: %s', p_exercise_type::text));
            v_details := jsonb_build_object('error', 'unsupported_type', 'type', p_exercise_type::text);

    END CASE;

    -- ========================================================================
    -- 3. CONSTRUIR RESULTADO
    -- ========================================================================
    is_valid := (array_length(v_errors, 1) IS NULL OR array_length(v_errors, 1) = 0);
    validation_errors := COALESCE(v_errors, ARRAY[]::TEXT[]);
    requires_manual_review := TRUE;  -- SIEMPRE true para M4-M5
    details := v_details;

END;
$$;


ALTER FUNCTION educational_content.validate_module4_module5_answer(p_exercise_type educational_content.exercise_type, p_submitted_answer jsonb, p_max_points integer, OUT is_valid boolean, OUT validation_errors text[], OUT requires_manual_review boolean, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_module4_module5_answer(p_exercise_type educational_content.exercise_type, p_submitted_answer jsonb, p_max_points integer, OUT is_valid boolean, OUT validation_errors text[], OUT requires_manual_review boolean, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_module4_module5_answer(p_exercise_type educational_content.exercise_type, p_submitted_answer jsonb, p_max_points integer, OUT is_valid boolean, OUT validation_errors text[], OUT requires_manual_review boolean, OUT details jsonb) IS 'Validador de estructura JSONB para ejercicios de Módulos 4 y 5.

IMPORTANTE: NO evalúa calidad de contenido (eso es responsabilidad del docente).
SÍ valida que la estructura de respuesta sea correcta.
SIEMPRE retorna requires_manual_review=TRUE.

Tipos soportados:
  Módulo 4 (5 tipos):
    - verificador_fake_news: Validar claims_verified[] con estructura correcta
    - infografia_interactiva: Validar answers{} y sections_explored[]
    - quiz_tiktok: Validar answers[] de integers
    - navegacion_hipertextual: Validar path[] e information_found{}
    - analisis_memes: Validar annotations[] y analysis{}

  Módulo 5 (3 tipos):
    - diario_multimedia: Validar entries[] con date/content
    - comic_digital: Validar panels[] con dialogue/narration
    - video_carta: Validar video_url O script, y duration

Parámetros:
  - p_exercise_type: Tipo de ejercicio (verificador_fake_news, diario_multimedia, etc.)
  - p_submitted_answer: Respuesta del estudiante en formato JSONB
  - p_max_points: Puntuación máxima (para contexto, no se usa en scoring)

Retorna:
  - is_valid: TRUE si estructura válida, FALSE si hay errores
  - validation_errors: Array de mensajes de error descriptivos (vacío si válido)
  - requires_manual_review: SIEMPRE TRUE (estos ejercicios requieren revisión docente)
  - details: Información adicional de validación (métricas, estructura encontrada)

Ejemplos de uso en 05-DOCUMENTACION.md';


--
-- Name: validate_podcast_argumentativo(jsonb, jsonb, integer, jsonb); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_podcast_argumentativo(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_special_rules jsonb DEFAULT '{}'::jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_audio_url TEXT;
    v_duration_seconds INTEGER;
    v_file_format TEXT;
    v_file_size_mb NUMERIC;
    v_min_duration INTEGER;
    v_max_duration INTEGER;
    v_max_size_mb NUMERIC;
    v_allowed_formats TEXT[];
    v_format_valid BOOLEAN := false;
    v_duration_valid BOOLEAN := false;
    v_size_valid BOOLEAN := false;
    v_has_metadata BOOLEAN := false;
BEGIN
    -- Extraer datos del audio enviado
    v_audio_url := p_submitted_answer->>'audio_url';
    v_duration_seconds := (p_submitted_answer->>'duration_seconds')::integer;
    v_file_format := LOWER(TRIM(COALESCE(p_submitted_answer->>'file_format', '')));
    v_file_size_mb := (p_submitted_answer->>'file_size_mb')::numeric;

    -- Verificar que se proporcionó un audio
    IF v_audio_url IS NULL OR TRIM(v_audio_url) = '' THEN
        is_correct := false;
        score := 0;
        feedback := 'No se proporcionó ningún archivo de audio.';
        details := jsonb_build_object('error', 'missing_audio');
        RETURN;
    END IF;

    -- Extraer configuración
    v_min_duration := COALESCE(
        (p_solution->>'min_duration_seconds')::integer,
        (p_special_rules->>'min_duration_seconds')::integer,
        120  -- 2 minutos por defecto
    );

    v_max_duration := COALESCE(
        (p_solution->>'max_duration_seconds')::integer,
        (p_special_rules->>'max_duration_seconds')::integer,
        600  -- 10 minutos por defecto
    );

    v_max_size_mb := COALESCE(
        (p_solution->>'max_size_mb')::numeric,
        (p_special_rules->>'max_size_mb')::numeric,
        50.0  -- 50 MB por defecto
    );

    -- Formatos permitidos
    v_allowed_formats := COALESCE(
        ARRAY(SELECT jsonb_array_elements_text(p_solution->'allowed_formats')),
        ARRAY(SELECT jsonb_array_elements_text(p_special_rules->'allowed_formats')),
        ARRAY['mp3', 'm4a', 'wav', 'ogg', 'aac']
    );

    -- Validar formato
    IF v_file_format = ANY(v_allowed_formats) THEN
        v_format_valid := true;
    END IF;

    -- Validar duración
    IF v_duration_seconds IS NOT NULL
       AND v_duration_seconds >= v_min_duration
       AND v_duration_seconds <= v_max_duration THEN
        v_duration_valid := true;
    END IF;

    -- Validar tamaño
    IF v_file_size_mb IS NOT NULL AND v_file_size_mb <= v_max_size_mb THEN
        v_size_valid := true;
    END IF;

    -- Verificar metadata adicional (título, descripción)
    IF (p_submitted_answer->>'title') IS NOT NULL
       AND TRIM(p_submitted_answer->>'title') != ''
       AND (p_submitted_answer->>'description') IS NOT NULL
       AND TRIM(p_submitted_answer->>'description') != '' THEN
        v_has_metadata := true;
    END IF;

    -- Calcular score técnico
    -- NOTA: Este validador solo verifica criterios técnicos
    -- La calidad del contenido debe ser evaluada manualmente por el profesor
    score := 0;

    -- 30% formato válido
    IF v_format_valid THEN
        score := score + ROUND(p_max_points * 0.30);
    END IF;

    -- 40% duración válida
    IF v_duration_valid THEN
        score := score + ROUND(p_max_points * 0.40);
    ELSIF v_duration_seconds IS NOT NULL THEN
        -- Puntos parciales si está cerca del rango
        IF v_duration_seconds < v_min_duration THEN
            score := score + ROUND((v_duration_seconds::NUMERIC / v_min_duration) * (p_max_points * 0.40));
        ELSIF v_duration_seconds > v_max_duration THEN
            score := score + ROUND(p_max_points * 0.20);  -- Penalización por exceso
        END IF;
    END IF;

    -- 20% tamaño válido
    IF v_size_valid THEN
        score := score + ROUND(p_max_points * 0.20);
    END IF;

    -- 10% metadata completo
    IF v_has_metadata THEN
        score := score + ROUND(p_max_points * 0.10);
    END IF;

    -- Validación técnica completa = 100%
    -- PERO se requiere revisión manual del profesor
    is_correct := (v_format_valid AND v_duration_valid AND v_size_valid);

    -- Feedback
    IF is_correct THEN
        feedback := format('Audio recibido correctamente. Duración: %s segundos. Formato: %s. Pendiente revisión de contenido.',
                          v_duration_seconds, UPPER(v_file_format));
    ELSE
        feedback := 'Errores técnicos: ';
        IF NOT v_format_valid THEN
            feedback := feedback || format('Formato no válido (%s). ', COALESCE(v_file_format, 'desconocido'));
        END IF;
        IF NOT v_duration_valid THEN
            feedback := feedback || format('Duración fuera de rango (necesitas %s-%s seg, tienes %s). ',
                                          v_min_duration, v_max_duration, COALESCE(v_duration_seconds, 0));
        END IF;
        IF NOT v_size_valid THEN
            feedback := feedback || format('Archivo muy grande (máx %s MB). ', v_max_size_mb);
        END IF;
    END IF;

    -- Details
    details := jsonb_build_object(
        'validation_type', 'technical',
        'requires_manual_review', true,
        'audio_url', v_audio_url,
        'duration_seconds', v_duration_seconds,
        'file_format', v_file_format,
        'file_size_mb', v_file_size_mb,
        'format_valid', v_format_valid,
        'duration_valid', v_duration_valid,
        'size_valid', v_size_valid,
        'has_metadata', v_has_metadata,
        'allowed_formats', array_to_json(v_allowed_formats),
        'duration_range', jsonb_build_object(
            'min_seconds', v_min_duration,
            'max_seconds', v_max_duration
        )
    );
END;
$$;


ALTER FUNCTION educational_content.validate_podcast_argumentativo(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_special_rules jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) OWNER TO postgres;

--
-- Name: FUNCTION validate_podcast_argumentativo(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_special_rules jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb); Type: COMMENT; Schema: educational_content; Owner: postgres
--

COMMENT ON FUNCTION educational_content.validate_podcast_argumentativo(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_special_rules jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) IS 'Validador TÉCNICO para podcast argumentativo (Módulo 3 - Pensamiento Crítico).
Valida formato, duración, tamaño del archivo de audio.
IMPORTANTE: NO valida calidad del contenido - requiere revisión manual del profesor.
Este validador solo verifica criterios técnicos.';


--
-- Name: validate_prediccion_narrativa(jsonb, jsonb, integer, numeric, boolean, jsonb); Type: FUNCTION; Schema: educational_content; Owner: postgres
--

CREATE FUNCTION educational_content.validate_prediccion_narrativa(p_solution jsonb, p_submitted_answer jsonb, p_max_points integer, p_fuzzy_threshold numeric DEFAULT 0.70, p_normalize_text boolean DEFAULT true, p_special_rules jsonb DEFAULT '{}'::jsonb, OUT is_correct boolean, OUT score integer, OUT feedback text, OUT details jsonb) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_prediction TEXT;
    v_keywords JSONB;
    v_min_words INTEGER;
    v_word_count INTEGER;
    v_keywords_found INTEGER := 0;
    v_total_keywords INTEGER;
    v_keyword TEXT;
    v_normalized_prediction TEXT;
BEGIN
    -- Extraer predicción enviada
    v_prediction := p_submitted_answer->>'prediction';

    IF v_prediction IS NULL OR TRIM(v_prediction) = '' THEN
        is_correct := false;
        score := 0;
        feedback := 'No se proporcionó ninguna predicción.';
        details := jsonb_build_object('error', 'empty_prediction');
        RETURN;
    END IF;

    -- Extraer configuración
    v_keywords := p_solution->'keywords';
    v_min_words := COALESCE((p_solution->>'min_words')::integer, (p_special_rules->>'min_word_count')::integer, 30);

    -- Contar palabras
    v_word_count := array_length(string_to_array(TRIM(v_prediction), ' '), 1);

    -- Normalizar
    IF p_normalize_text THEN
        v_normalized_prediction := LOWER(gamilit.normalize_text(v_prediction));
    ELSE
        v_normalized_prediction := LOWER(v_prediction);
    END IF;

    -- Contar keywords
    IF v_keywords IS NOT NULL THEN
        v_total_keywords := jsonb_array_length(v_keywords);

        FOR v_keyword IN SELECT jsonb_array_elements_text(v_keywords)
        LOOP
            IF p_normalize_text THEN
                v_keyword := LOWER(gamilit.normalize_text(v_keyword));
            ELSE
                v_keyword := LOWER(v_keyword);
            END IF;

            IF v_normalized_prediction LIKE '%' || v_keyword || '%' THEN
                v_keywords_found := v_keywords_found + 1;
            END IF;
        END LOOP;
    ELSE
        v_total_keywords := 0;
    END IF;

    -- Calcular score (similar a construccion_hipotesis)
    IF v_word_count >= v_min_words THEN
        score := p_max_points / 2;
    ELSE
        score := ROUND((v_word_count::NUMERIC / v_min_words) * (p_max_points / 2));
    END IF;

    IF v_total_keywords > 0 THEN
        score := score + ROUND((v_keywords_found::NUMERIC / v_total_keywords) * (p_max_points / 2));
    END IF;

    is_correct := (score >= (p_max_points * 0.70));

    -- Feedback
    IF is_correct THEN
        feedback := format('Buena predicción narrativa. %s palabras, %s/%s keywords.',
                          v_word_count, v_keywords_found, v_total_keywords);
    ELSE
        feedback := format('Predicción incompleta. Necesitas al menos %s palabras (tienes %s).',
                          v_min_words, v_word_count);
    END IF;

    -- Details
    details := jsonb_build_object(
        'word_count', v_word_count,
        'min_words_required', v_min_words,
        'keywords_found', v_keywords_found,
        'total_keywords', v_total_keywords,
        'validation_type', 'heuristic'
    );
END;
$$;


