-- Name: get_rank_multiplier(gamification_system.maya_rank); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.get_rank_multiplier(p_rank gamification_system.maya_rank) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_multiplier NUMERIC(3,2);
BEGIN
    -- Obtener multiplicador desde maya_ranks table
    SELECT xp_multiplier
    INTO v_multiplier
    FROM gamification_system.maya_ranks
    WHERE rank_name = p_rank
      AND is_active = true;

    -- Si no se encuentra, retornar 1.00 (sin bonus)
    IF NOT FOUND OR v_multiplier IS NULL THEN
        RETURN 1.00;
    END IF;

    RETURN v_multiplier;
END;
$$;


