--
-- Name: process_exercise_completion(uuid, uuid, integer); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.process_exercise_completion(p_user_id uuid, p_exercise_id uuid, p_xp_earned integer DEFAULT 100) RETURNS TABLE(user_id uuid, xp_awarded integer, coins_awarded integer, level_up boolean, achievement_triggered character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_old_level INTEGER;
    v_new_level INTEGER;
    v_coins_reward INTEGER;
BEGIN
    -- Obtener nivel actual del usuario
    SELECT level INTO v_old_level
    FROM gamification_system.user_stats
    WHERE user_id = p_user_id;

    IF NOT FOUND THEN
        RETURN;
    END IF;

    -- Calcular recompensa en coins (10% del XP)
    v_coins_reward := (p_xp_earned / 10)::INTEGER;

    -- Actualizar XP y coins
    UPDATE gamification_system.user_stats
    SET
        total_xp = total_xp + p_xp_earned,
        ml_coins = ml_coins + v_coins_reward,
        updated_at = NOW()
    WHERE user_id = p_user_id;

    -- Calcular nuevo nivel
    SELECT total_xp INTO v_new_level
    FROM gamification_system.user_stats
    WHERE user_id = p_user_id;
    
    v_new_level := (v_new_level / 1000)::INTEGER + 1;

    RETURN QUERY SELECT
        p_user_id,
        p_xp_earned,
        v_coins_reward,
        v_new_level > v_old_level,
        'EXERCISE_COMPLETED'::VARCHAR;
END;
$$;


