-- Name: trg_check_rank_promotion_fn(); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.trg_check_rank_promotion_fn() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Solo verificar si total_xp aumentó
    IF NEW.total_xp > OLD.total_xp THEN
        -- Llamar a función de verificación de promoción
        PERFORM gamification_system.check_rank_promotion(NEW.user_id);
    END IF;

    RETURN NEW;
END;
$$;


