--
-- Name: initialize_module_progress_for_users(uuid); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.initialize_module_progress_for_users(p_module_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gamilit', 'auth_management', 'educational_content', 'progress_tracking'
    AS $$
DECLARE
    v_records_created INTEGER := 0;
    v_module_exists BOOLEAN;
BEGIN
    -- Si no se especifica módulo, inicializar TODOS los módulos publicados
    IF p_module_id IS NULL THEN
        -- Crear registros para TODOS los módulos publicados y usuarios elegibles
        INSERT INTO progress_tracking.module_progress (
            user_id,
            module_id,
            status,
            progress_percentage,
            created_at,
            updated_at
        )
        SELECT
            p.id AS user_id,
            m.id AS module_id,
            'not_started'::progress_tracking.progress_status,
            0,
            NOW(),
            NOW()
        FROM auth_management.profiles p
        CROSS JOIN educational_content.modules m
        WHERE p.role IN ('student', 'admin_teacher', 'super_admin')
          AND m.is_published = true
          AND m.status = 'published'
          AND NOT EXISTS (
              SELECT 1 FROM progress_tracking.module_progress mp
              WHERE mp.user_id = p.id AND mp.module_id = m.id
          )
        ON CONFLICT (user_id, module_id) DO NOTHING;

        GET DIAGNOSTICS v_records_created = ROW_COUNT;

        IF v_records_created > 0 THEN
            RAISE NOTICE '[initialize_module_progress] Created % records for all published modules', v_records_created;
        END IF;

        RETURN v_records_created;
    END IF;

    -- Verificar que el módulo existe y está publicado
    SELECT EXISTS (
        SELECT 1 FROM educational_content.modules
        WHERE id = p_module_id
          AND is_published = true
          AND status = 'published'
    ) INTO v_module_exists;

    IF NOT v_module_exists THEN
        RAISE NOTICE '[initialize_module_progress] Module % not found or not published', p_module_id;
        RETURN 0;
    END IF;

    -- Crear registros de progress para todos los usuarios elegibles
    INSERT INTO progress_tracking.module_progress (
        user_id,
        module_id,
        status,
        progress_percentage,
        created_at,
        updated_at
    )
    SELECT
        p.id AS user_id,
        p_module_id AS module_id,
        'not_started'::progress_tracking.progress_status,
        0,
        NOW(),
        NOW()
    FROM auth_management.profiles p
    WHERE p.role IN ('student', 'admin_teacher', 'super_admin')
      AND NOT EXISTS (
          SELECT 1 FROM progress_tracking.module_progress mp
          WHERE mp.user_id = p.id AND mp.module_id = p_module_id
      )
    ON CONFLICT (user_id, module_id) DO NOTHING;

    GET DIAGNOSTICS v_records_created = ROW_COUNT;

    IF v_records_created > 0 THEN
        RAISE NOTICE '[initialize_module_progress] Created % progress records for module %',
            v_records_created, p_module_id;
    END IF;

    RETURN v_records_created;
END;
$$;


ALTER FUNCTION gamilit.initialize_module_progress_for_users(p_module_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION initialize_module_progress_for_users(p_module_id uuid); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.initialize_module_progress_for_users(p_module_id uuid) IS 'Inicializa registros de module_progress para un módulo nuevo o todos los módulos publicados.
Complementa trg_initialize_user_stats para mantener sincronizados usuarios y módulos.';


--
-- Name: initialize_module_progress_on_publish(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.initialize_module_progress_on_publish() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gamilit', 'auth_management', 'educational_content', 'progress_tracking'
    AS $$
DECLARE
    v_records_created INTEGER;
BEGIN
    -- Solo ejecutar si el módulo está publicado
    -- Para INSERT: verificar que el nuevo registro está publicado
    -- Para UPDATE: verificar que cambió de no-publicado a publicado
    IF TG_OP = 'INSERT' THEN
        IF NEW.is_published = true AND NEW.status = 'published' THEN
            v_records_created := gamilit.initialize_module_progress_for_users(NEW.id);
            RAISE NOTICE '[trg_initialize_module_progress] INSERT: Created % records for module %',
                v_records_created, NEW.id;
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        -- Solo si cambió de no-publicado a publicado
        IF (OLD.is_published = false OR OLD.status != 'published')
           AND NEW.is_published = true
           AND NEW.status = 'published' THEN
            v_records_created := gamilit.initialize_module_progress_for_users(NEW.id);
            RAISE NOTICE '[trg_initialize_module_progress] UPDATE: Created % records for module %',
                v_records_created, NEW.id;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION gamilit.initialize_module_progress_on_publish() OWNER TO postgres;

--
-- Name: FUNCTION initialize_module_progress_on_publish(); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.initialize_module_progress_on_publish() IS 'Trigger function que inicializa module_progress cuando un módulo se publica';


--
-- Name: initialize_user_missions(uuid); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.initialize_user_missions(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_today_start TIMESTAMP;
    v_today_end TIMESTAMP;
    v_week_end TIMESTAMP;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_code TEXT;
BEGIN
    -- Calculate mission date ranges using Mexico timezone
    v_today_start := gamilit.now_mexico()::date;
    v_today_end := v_today_start + INTERVAL '23 hours 59 minutes';
    v_week_end := v_today_start + INTERVAL '7 days';

    -- =====================================================
    -- DAILY MISSIONS (3)
    -- =====================================================

    -- Daily Mission 1: Complete exercises
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        'daily_complete_exercises',
        'Completar 3 ejercicios',
        'Completa 3 ejercicios hoy para ganar recompensas',
        'daily',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'complete_exercises',
                'target', 3,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 50,
            'ml_coins', 25
        ),
        'active',
        0,
        v_today_start,
        v_today_end
    )
    ON CONFLICT DO NOTHING;

    -- Daily Mission 2: Earn XP
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        'daily_earn_xp',
        'Ganar 100 XP',
        'Acumula 100 puntos de experiencia hoy',
        'daily',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'earn_xp',
                'target', 100,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 30,
            'ml_coins', 15
        ),
        'active',
        0,
        v_today_start,
        v_today_end
    )
    ON CONFLICT DO NOTHING;

    -- Daily Mission 3: Use comodín
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        'daily_use_comodin',
        'Usar un comodín',
        'Usa al menos un comodín en un ejercicio',
        'daily',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'use_comodines',
                'target', 1,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 20,
            'ml_coins', 10
        ),
        'active',
        0,
        v_today_start,
        v_today_end
    )
    ON CONFLICT DO NOTHING;

    -- =====================================================
    -- WEEKLY MISSIONS (5)
    -- =====================================================

    -- Weekly Mission 1: Complete a module
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        'weekly_complete_module',
        'Completar un módulo',
        'Completa un módulo completo esta semana',
        'weekly',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'complete_modules',
                'target', 1,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 200,
            'ml_coins', 100
        ),
        'active',
        0,
        v_today_start,
        v_week_end
    )
    ON CONFLICT DO NOTHING;

    -- Weekly Mission 2: Daily streak
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        'weekly_daily_streak',
        'Racha de 5 días',
        'Completa al menos un ejercicio durante 5 días seguidos',
        'weekly',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'daily_streak',
                'target', 5,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 150,
            'ml_coins', 75
        ),
        'active',
        0,
        v_today_start,
        v_week_end
    )
    ON CONFLICT DO NOTHING;

    -- Weekly Mission 3: Perfect scores
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        'weekly_perfect_scores',
        'Perfección absoluta',
        'Obtén 3 puntajes perfectos (100%) en ejercicios',
        'weekly',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'perfect_scores',
                'target', 3,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 180,
            'ml_coins', 90
        ),
        'active',
        0,
        v_today_start,
        v_week_end
    )
    ON CONFLICT DO NOTHING;

    -- Weekly Mission 4: Explorer
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        'weekly_explorer',
        'Explorador curioso',
        'Completa ejercicios de 3 módulos diferentes',
        'weekly',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'explore_modules',
                'target', 3,
                'current', 0,
                'modules_visited', '[]'::jsonb
            )
        ),
        jsonb_build_object(
            'xp', 120,
            'ml_coins', 60
        ),
        'active',
        0,
        v_today_start,
        v_week_end
    )
    ON CONFLICT DO NOTHING;

    -- Weekly Mission 5: Master learner
    INSERT INTO gamification_system.missions (
        user_id,
        template_id,
        title,
        description,
        mission_type,
        objectives,
        rewards,
        status,
        progress,
        start_date,
        end_date
    ) VALUES (
        p_user_id,
        'weekly_master_learner',
        'Maestro del aprendizaje',
        'Completa 15 ejercicios esta semana',
        'weekly',
        jsonb_build_array(
            jsonb_build_object(
                'type', 'complete_exercises',
                'target', 15,
                'current', 0
            )
        ),
        jsonb_build_object(
            'xp', 250,
            'ml_coins', 125
        ),
        'active',
        0,
        v_today_start,
        v_week_end
    )
    ON CONFLICT DO NOTHING;

EXCEPTION
    WHEN OTHERS THEN
        -- P1-001: Capturar error sin propagar, ya que initialize_user_stats maneja el error general
        GET STACKED DIAGNOSTICS
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_code = RETURNED_SQLSTATE;

        RAISE WARNING '[P1-001] Error inicializando misiones para usuario %: % (SQLSTATE: %)',
            p_user_id, v_error_message, v_error_code;

        -- Registrar en pending_user_initialization para retry posterior
        BEGIN
            INSERT INTO audit_logging.pending_user_initialization (
                user_id,
                profile_id,
                error_message,
                error_code,
                error_detail,
                trigger_name,
                function_name,
                status,
                next_retry_at
            ) VALUES (
                p_user_id,
                p_user_id,
                v_error_message,
                v_error_code,
                v_error_detail,
                'initialize_user_stats',
                'gamilit.initialize_user_missions',
                'pending',
                gamilit.now_mexico() + INTERVAL '5 minutes'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[P1-001] No se pudo registrar error de misiones: %', SQLERRM;
        END;
        -- No re-lanzar excepción, el usuario aún puede usar la plataforma sin misiones
END;
$$;


ALTER FUNCTION gamilit.initialize_user_missions(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION initialize_user_missions(p_user_id uuid); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.initialize_user_missions(p_user_id uuid) IS 'Inicializa misiones diarias (3) y semanales (5) para un usuario nuevo. Llamada automáticamente durante el registro de usuarios con rol student, admin_teacher o super_admin.';


--
-- Name: initialize_user_stats(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.initialize_user_stats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gamilit', 'auth_management', 'gamification_system', 'progress_tracking', 'social_features', 'audit_logging'
    AS $$
DECLARE
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_code TEXT;
BEGIN
    -- Initialize gamification for students, teachers, and admins
    -- Only these roles have gamification enabled
    IF NEW.role IN ('student', 'admin_teacher', 'super_admin') THEN
        -- DB-125: user_stats.user_id FK apunta a profiles(id), usar NEW.id
        INSERT INTO gamification_system.user_stats (
            user_id,
            tenant_id,
            ml_coins,
            ml_coins_earned_total
        ) VALUES (
            NEW.id,  -- DB-125: CORREGIDO - usar profiles.id, no profiles.user_id
            NEW.tenant_id,
            100, -- Welcome bonus
            100
        )
        ON CONFLICT (user_id) DO NOTHING;  -- Prevent duplicates

        -- [2025-12-28] Registrar transaccion de bono de bienvenida para auditoria
        -- [2026-01-04] CORREGIDO: Eliminada columna 'source' inexistente, usando reference_type y metadata
        INSERT INTO gamification_system.ml_coins_transactions (
            user_id,
            tenant_id,
            amount,
            balance_before,
            balance_after,
            transaction_type,
            description,
            reason,
            reference_type,
            metadata
        ) VALUES (
            NEW.id,
            NEW.tenant_id,
            100,  -- Welcome bonus
            0,    -- Balance antes (nuevo usuario)
            100,  -- Balance despues
            'earn',
            'Bono de bienvenida al registrarte en GAMILIT',
            'system_welcome_bonus',
            'admin',  -- Tipo admin para acciones del sistema
            jsonb_build_object(
                'trigger', 'initialize_user_stats',
                'version', '2.1',
                'source', 'system_welcome_bonus',
                'created_at', gamilit.now_mexico()::text
            )
        )
        ON CONFLICT DO NOTHING;

        -- Create comodines inventory
        -- IMPORTANT: comodines_inventory.user_id references profiles.id (NOT auth.users.id)
        INSERT INTO gamification_system.comodines_inventory (
            user_id
        ) VALUES (
            NEW.id  -- CORRECTED: usar NEW.id (profiles.id) porque FK apunta a profiles(id)
        )
        ON CONFLICT (user_id) DO NOTHING;

        -- [2025-12-28] Crear preferencias de usuario con valores default
        -- SECURITY DEFINER permite bypass de RLS en esta tabla
        INSERT INTO auth_management.user_preferences (
            user_id,
            theme,
            language,
            notifications_enabled,
            email_notifications,
            sound_enabled,
            tutorial_completed,
            preferences
        ) VALUES (
            NEW.id,
            'light',        -- Tema default
            'es',           -- Idioma español
            true,           -- Notificaciones habilitadas
            true,           -- Email notifications habilitadas
            true,           -- Sonido habilitado
            false,          -- Tutorial pendiente
            jsonb_build_object(
                'gamification_hints', true,
                'show_leaderboard', true,
                'auto_play_audio', false
            )
        )
        ON CONFLICT (user_id) DO NOTHING;

        -- Create initial user rank (starting with Ajaw - lowest rank)
        -- BUG FIX #2: Use WHERE NOT EXISTS instead of ON CONFLICT (no unique constraint on user_id)
        -- 2025-12-26: Agregado is_current = true explícitamente
        -- DB-125: user_ranks.user_id FK apunta a profiles(id), usar NEW.id
        INSERT INTO gamification_system.user_ranks (
            user_id,
            tenant_id,
            current_rank,
            is_current,
            achieved_at
        )
        SELECT
            NEW.id,  -- DB-125: CORREGIDO - usar profiles.id, no profiles.user_id
            NEW.tenant_id,
            'Ajaw'::gamification_system.maya_rank,
            true,
            gamilit.now_mexico()
        WHERE NOT EXISTS (
            SELECT 1 FROM gamification_system.user_ranks WHERE user_id = NEW.id
        );

        -- BUG FIX #1: Initialize module progress for all active modules
        -- CRITICAL: New users must see available modules immediately
        -- This was missing and caused "no modules available" errors
        -- IMPORTANT: module_progress.user_id references profiles.id (NOT auth.users.id)
        INSERT INTO progress_tracking.module_progress (
            user_id,
            module_id,
            status,
            progress_percentage,
            created_at,
            updated_at
        )
        SELECT
            NEW.id,  -- FIXED: Use NEW.id (profiles.id) not NEW.user_id (auth.users.id)
            m.id,
            'not_started'::progress_tracking.progress_status,
            0,
            NOW(),
            NOW()
        FROM educational_content.modules m
        WHERE m.is_published = true
          AND m.status = 'published'
        ON CONFLICT (user_id, module_id) DO NOTHING;

        -- Initialize daily and weekly missions for new users
        PERFORM gamilit.initialize_user_missions(NEW.id);

        -- [2025-12-28] Inicializacion especifica para profesores
        IF NEW.role = 'admin_teacher' THEN
            -- Crear reporte inicial mensual para el profesor
            INSERT INTO social_features.teacher_reports (
                teacher_id,
                tenant_id,
                report_name,
                report_type,
                report_format,
                period_start,
                period_end,
                status,
                metadata
            ) VALUES (
                NEW.id,
                NEW.tenant_id,
                'Reporte Mensual Inicial - ' || to_char(gamilit.now_mexico(), 'Month YYYY'),
                'monthly',
                'pdf',
                date_trunc('month', gamilit.now_mexico()),
                date_trunc('month', gamilit.now_mexico()) + INTERVAL '1 month' - INTERVAL '1 day',
                'pending',
                jsonb_build_object(
                    'auto_created', true,
                    'trigger', 'initialize_user_stats',
                    'description', 'Reporte automatico creado al registrar profesor'
                )
            )
            ON CONFLICT DO NOTHING;
        END IF;

    END IF;

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        -- Capture error details
        GET STACKED DIAGNOSTICS
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_code = RETURNED_SQLSTATE;

        -- Log warning but DO NOT block user creation
        RAISE WARNING '[P0-001] Error initializing gamification for user %: % (SQLSTATE: %)',
            NEW.user_id, v_error_message, v_error_code;

        -- Record in pending_user_initialization for retry
        BEGIN
            INSERT INTO audit_logging.pending_user_initialization (
                user_id,
                profile_id,
                tenant_id,
                error_message,
                error_code,
                error_detail,
                trigger_name,
                function_name,
                status,
                next_retry_at
            ) VALUES (
                NEW.user_id,
                NEW.id,
                NEW.tenant_id,
                v_error_message,
                v_error_code,
                v_error_detail,
                TG_NAME,
                'gamilit.initialize_user_stats',
                'pending',
                gamilit.now_mexico() + INTERVAL '5 minutes'
            );
        EXCEPTION
            WHEN OTHERS THEN
                -- If even logging fails, just warn and continue
                RAISE WARNING '[P0-001] Could not log initialization error: %', SQLERRM;
        END;

        -- CRITICAL: Still return NEW to allow profile creation to succeed
        -- User will be flagged for manual initialization
        RETURN NEW;
END;
$$;


ALTER FUNCTION gamilit.initialize_user_stats() OWNER TO postgres;

--
-- Name: FUNCTION initialize_user_stats(); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.initialize_user_stats() IS 'Inicializa estadísticas de gamificación para nuevos usuarios';


--
-- Name: initialize_user_stats_for_user(uuid); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.initialize_user_stats_for_user(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gamilit', 'auth_management', 'gamification_system', 'progress_tracking', 'social_features'
    AS $$
DECLARE
    v_profile RECORD;
BEGIN
    -- Obtener perfil del usuario
    SELECT id, user_id, tenant_id, role
    INTO v_profile
    FROM auth_management.profiles
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RAISE WARNING 'Profile not found for user_id: %', p_user_id;
        RETURN FALSE;
    END IF;

    -- Solo procesar roles con gamificacion
    IF v_profile.role NOT IN ('student', 'admin_teacher', 'super_admin') THEN
        RETURN TRUE;  -- OK, no requiere inicializacion
    END IF;

    -- Inicializar user_stats si no existe
    INSERT INTO gamification_system.user_stats (
        user_id,
        tenant_id,
        ml_coins,
        ml_coins_earned_total
    ) VALUES (
        v_profile.id,
        v_profile.tenant_id,
        100,
        100
    )
    ON CONFLICT (user_id) DO NOTHING;

    -- Inicializar comodines_inventory si no existe
    INSERT INTO gamification_system.comodines_inventory (user_id)
    VALUES (v_profile.id)
    ON CONFLICT (user_id) DO NOTHING;

    -- Inicializar user_preferences si no existe
    INSERT INTO auth_management.user_preferences (
        user_id,
        theme,
        language,
        notifications_enabled,
        email_notifications,
        sound_enabled,
        tutorial_completed,
        preferences
    ) VALUES (
        v_profile.id,
        'light',
        'es',
        true,
        true,
        true,
        false,
        jsonb_build_object(
            'gamification_hints', true,
            'show_leaderboard', true,
            'auto_play_audio', false
        )
    )
    ON CONFLICT (user_id) DO NOTHING;

    -- Inicializar user_ranks si no existe
    INSERT INTO gamification_system.user_ranks (
        user_id,
        tenant_id,
        current_rank,
        is_current,
        achieved_at
    )
    SELECT
        v_profile.id,
        v_profile.tenant_id,
        'Ajaw'::gamification_system.maya_rank,
        true,
        gamilit.now_mexico()
    WHERE NOT EXISTS (
        SELECT 1 FROM gamification_system.user_ranks WHERE user_id = v_profile.id
    );

    -- Inicializar module_progress para modulos publicados
    INSERT INTO progress_tracking.module_progress (
        user_id,
        module_id,
        status,
        progress_percentage,
        created_at,
        updated_at
    )
    SELECT
        v_profile.id,
        m.id,
        'not_started'::progress_tracking.progress_status,
        0,
        NOW(),
        NOW()
    FROM educational_content.modules m
    WHERE m.is_published = true
      AND m.status = 'published'
    ON CONFLICT (user_id, module_id) DO NOTHING;

    -- Inicializar misiones
    PERFORM gamilit.initialize_user_missions(v_profile.id);

    RETURN TRUE;

EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Error in initialize_user_stats_for_user(%): %', p_user_id, SQLERRM;
    RETURN FALSE;
END;
$$;


ALTER FUNCTION gamilit.initialize_user_stats_for_user(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION initialize_user_stats_for_user(p_user_id uuid); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.initialize_user_stats_for_user(p_user_id uuid) IS 'Wrapper callable para reintentar inicializacion de user_stats.
Usado por audit_logging.retry_pending_initializations() para usuarios que fallaron durante trigger.
A diferencia de initialize_user_stats() (trigger), esta funcion recibe user_id directamente.';


--
-- Name: is_admin(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.is_admin() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    -- Verifica si el usuario actual tiene rol de administrador
    RETURN EXISTS (
        SELECT 1
        FROM auth_management.profiles
        WHERE id = gamilit.get_current_user_id()
        AND role IN ('admin_teacher', 'super_admin')
        AND status = 'active'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$;


ALTER FUNCTION gamilit.is_admin() OWNER TO postgres;

--
-- Name: FUNCTION is_admin(); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.is_admin() IS 'Retorna TRUE si el usuario actual es administrador (admin_teacher o super_admin). Utilizada por políticas RLS para control de acceso administrativo. Verifica también que el usuario esté activo para prevenir acceso de usuarios suspendidos.';


--
-- Name: normalize_text(text); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.normalize_text(p_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_normalized TEXT;
BEGIN
    -- Manejar NULL
    IF p_text IS NULL OR TRIM(p_text) = '' THEN
        RETURN '';
    END IF;

    -- Normalizar texto:
    -- 1. Remover diacríticos (acentos) usando unaccent si está disponible
    -- 2. Normalizar espacios múltiples a uno solo
    -- 3. Trim espacios al inicio y fin

    v_normalized := p_text;

    -- Intentar usar unaccent si la extensión está instalada
    -- Si no está, fallback a reemplazos manuales básicos
    BEGIN
        v_normalized := unaccent(v_normalized);
    EXCEPTION WHEN undefined_function THEN
        -- Fallback: reemplazos manuales más comunes
        v_normalized := REPLACE(v_normalized, 'á', 'a');
        v_normalized := REPLACE(v_normalized, 'é', 'e');
        v_normalized := REPLACE(v_normalized, 'í', 'i');
        v_normalized := REPLACE(v_normalized, 'ó', 'o');
        v_normalized := REPLACE(v_normalized, 'ú', 'u');
        v_normalized := REPLACE(v_normalized, 'ñ', 'n');
        v_normalized := REPLACE(v_normalized, 'ü', 'u');
        v_normalized := REPLACE(v_normalized, 'Á', 'A');
        v_normalized := REPLACE(v_normalized, 'É', 'E');
        v_normalized := REPLACE(v_normalized, 'Í', 'I');
        v_normalized := REPLACE(v_normalized, 'Ó', 'O');
        v_normalized := REPLACE(v_normalized, 'Ú', 'U');
        v_normalized := REPLACE(v_normalized, 'Ñ', 'N');
        v_normalized := REPLACE(v_normalized, 'Ü', 'U');
    END;

    -- Normalizar espacios múltiples a uno solo
    v_normalized := REGEXP_REPLACE(v_normalized, '\s+', ' ', 'g');

    -- Trim espacios al inicio y fin
    v_normalized := TRIM(v_normalized);

    RETURN v_normalized;
END;
$$;


