-- Name: FUNCTION cleanup_rate_limit_logs(older_than_days integer); Type: COMMENT; Schema: notifications; Owner: postgres
--

COMMENT ON FUNCTION notifications.cleanup_rate_limit_logs(older_than_days integer) IS 'Cleanup old rate limit logs. Default: remove logs older than 30 days';


--
-- Name: get_user_preferences(uuid); Type: FUNCTION; Schema: notifications; Owner: postgres
--

CREATE FUNCTION notifications.get_user_preferences(p_user_id uuid) RETURNS TABLE(notification_type character varying, in_app_enabled boolean, email_enabled boolean, push_enabled boolean, email_frequency character varying, quiet_hours_start time without time zone, quiet_hours_end time without time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        np.notification_type,
        np.in_app_enabled,
        np.email_enabled,
        np.push_enabled,
        np.email_frequency,
        np.quiet_hours_start,
        np.quiet_hours_end
    FROM notifications.notification_preferences np
    WHERE np.user_id = p_user_id
    ORDER BY np.notification_type;
END;
$$;


