-- Name: FUNCTION update_difficulty_progress(p_user_id uuid, p_difficulty_level educational_content.difficulty_level, p_is_completed boolean, p_is_correct_first_attempt boolean, p_time_spent_seconds integer); Type: COMMENT; Schema: progress_tracking; Owner: postgres
