-- Name: has_blocked(uuid, uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.has_blocked(blocker_user_id uuid, target_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM social_features.user_blocks
        WHERE blocker_id = blocker_user_id
          AND blocked_id = target_user_id
    );
END;
$$;


