--
-- Name: is_blocked(uuid, uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.is_blocked(user1_id uuid, user2_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    -- Verificar si existe bloqueo en cualquier direccion
    -- user1 bloqueo a user2 OR user2 bloqueo a user1
    RETURN EXISTS (
        SELECT 1
        FROM social_features.user_blocks
        WHERE (blocker_id = user1_id AND blocked_id = user2_id)
           OR (blocker_id = user2_id AND blocked_id = user1_id)
    );
END;
$$;


ALTER FUNCTION social_features.is_blocked(user1_id uuid, user2_id uuid) OWNER TO postgres;

