    CONSTRAINT messages_recipient_or_classroom CHECK (((recipient_id IS NOT NULL) OR (classroom_id IS NOT NULL))),
    CONSTRAINT messages_type_valid CHECK (((message_type)::text = ANY ((ARRAY['direct'::character varying, 'classroom_announcement'::character varying, 'classroom_chat'::character varying, 'private_feedback'::character varying, 'assignment_comment'::character varying, 'system'::character varying])::text[])))
