--

CREATE TABLE social_features.challenge_results (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    challenge_id uuid NOT NULL,
    winner_id uuid,
    second_place_id uuid,
    third_place_id uuid,
    total_participants integer NOT NULL,
    participants_completed integer,
    participants_forfeit integer,
    winning_score numeric(10,2),
    average_score numeric(10,2),
    highest_accuracy numeric(5,2),
    average_completion_time_seconds integer,
    fastest_completion_time_seconds integer,
    total_xp_distributed integer DEFAULT 0,
    total_ml_coins_distributed integer DEFAULT 0,
    rewards_distributed boolean DEFAULT false,
    final_leaderboard jsonb DEFAULT '[]'::jsonb,
    statistics jsonb DEFAULT '{}'::jsonb,
    calculated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    rewards_distributed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    metadata jsonb DEFAULT '{}'::jsonb,
    CONSTRAINT chk_accuracy_percentage CHECK (((highest_accuracy IS NULL) OR ((highest_accuracy >= (0)::numeric) AND (highest_accuracy <= (100)::numeric)))),
    CONSTRAINT chk_completed_lte_total CHECK (((participants_completed IS NULL) OR (participants_completed <= total_participants))),
    CONSTRAINT chk_forfeit_lte_total CHECK (((participants_forfeit IS NULL) OR (participants_forfeit <= total_participants))),
    CONSTRAINT chk_positive_coins CHECK ((total_ml_coins_distributed >= 0)),
    CONSTRAINT chk_positive_participants CHECK ((total_participants > 0)),
    CONSTRAINT chk_positive_xp CHECK ((total_xp_distributed >= 0)),
    CONSTRAINT chk_rewards_timestamp CHECK (((rewards_distributed = false) OR (rewards_distributed_at IS NOT NULL)))
);


