-- Name: guild_emblems id; Type: DEFAULT; Schema: social_features; Owner: gamilit_user
--

ALTER TABLE ONLY social_features.guild_emblems ALTER COLUMN id SET DEFAULT nextval('social_features.guild_emblems_id_seq'::regclass);


