--
-- Name: exercise_submissions trg_create_manual_review_on_submission_update; Type: TRIGGER; Schema: progress_tracking; Owner: gamilit_user
--

CREATE TRIGGER trg_create_manual_review_on_submission_update AFTER UPDATE ON progress_tracking.exercise_submissions FOR EACH ROW WHEN (((new.status = 'submitted'::text) AND (old.status IS DISTINCT FROM 'submitted'::text))) EXECUTE FUNCTION progress_tracking.create_manual_review_on_submission();


--
-- Name: TRIGGER trg_create_manual_review_on_submission_update ON exercise_submissions; Type: COMMENT; Schema: progress_tracking; Owner: gamilit_user
--

COMMENT ON TRIGGER trg_create_manual_review_on_submission_update ON progress_tracking.exercise_submissions IS 'BUG-TEACHER-REVIEWS-002: Crea ManualReview automaticamente cuando una submission cambia de draft/pending_review a submitted via UPDATE. Complementa al trigger INSERT existente (16-trg_create_manual_review.sql). Usa la misma funcion create_manual_review_on_submission() que tiene ON CONFLICT DO NOTHING para evitar duplicados.';


