-- Name: TRIGGER trg_update_missions_on_streak ON exercise_attempts; Type: COMMENT; Schema: progress_tracking; Owner: gamilit_user
--

COMMENT ON TRIGGER trg_update_missions_on_streak ON progress_tracking.exercise_attempts IS 'Actualiza el progreso de misiones con objetivo correct_streak al completar ejercicios. Calcula la racha de ejercicios correctos consecutivos del usuario y actualiza las misiones correspondientes. Complementa el trigger 24 que maneja complete_exercises.';


--
-- Name: exercise_submissions trg_update_missions_on_submission; Type: TRIGGER; Schema: progress_tracking; Owner: gamilit_user
--

CREATE TRIGGER trg_update_missions_on_submission AFTER UPDATE ON progress_tracking.exercise_submissions FOR EACH ROW WHEN (((new.status = ANY (ARRAY['graded'::text, 'reviewed'::text])) AND (new.is_correct = true) AND ((old.status IS DISTINCT FROM new.status) OR (old.is_correct IS DISTINCT FROM new.is_correct)))) EXECUTE FUNCTION gamilit.trigger_missions_on_exercise_complete();


--
-- Name: TRIGGER trg_update_missions_on_submission ON exercise_submissions; Type: COMMENT; Schema: progress_tracking; Owner: gamilit_user
--

COMMENT ON TRIGGER trg_update_missions_on_submission ON progress_tracking.exercise_submissions IS 'Actualiza el progreso de misiones diarias/semanales cuando se califica un exercise_submission como correcto. Complementa el trigger de exercise_attempts para cubrir ejercicios con revisión manual. Usa la funcion wrapper trigger_missions_on_exercise_complete() (unificada 2025-12-29).';


--
-- Name: exercise_attempts trg_update_module_progress_on_exercise; Type: TRIGGER; Schema: progress_tracking; Owner: gamilit_user
--

CREATE TRIGGER trg_update_module_progress_on_exercise AFTER INSERT ON progress_tracking.exercise_attempts FOR EACH ROW EXECUTE FUNCTION gamilit.update_module_progress_on_exercise_complete();


--
-- Name: TRIGGER trg_update_module_progress_on_exercise ON exercise_attempts; Type: COMMENT; Schema: progress_tracking; Owner: gamilit_user
--

COMMENT ON TRIGGER trg_update_module_progress_on_exercise ON progress_tracking.exercise_attempts IS 'Actualiza el progreso del modulo correspondiente cuando se inserta un nuevo exercise_attempt. Solo cuenta ejercicios correctos unicos para el calculo de progreso.';


--
-- Name: exercise_submissions trg_update_submitted_progress_on_submission; Type: TRIGGER; Schema: progress_tracking; Owner: gamilit_user
--

CREATE TRIGGER trg_update_submitted_progress_on_submission AFTER INSERT ON progress_tracking.exercise_submissions FOR EACH ROW WHEN ((new.status <> 'draft'::text)) EXECUTE FUNCTION progress_tracking.update_submitted_progress_on_submission();


--
-- Name: TRIGGER trg_update_submitted_progress_on_submission ON exercise_submissions; Type: COMMENT; Schema: progress_tracking; Owner: gamilit_user
--

COMMENT ON TRIGGER trg_update_submitted_progress_on_submission ON progress_tracking.exercise_submissions IS 'FIX-DB-003-2026-01-18: Dispara actualizacion de submitted_progress al insertar submissions (excepto drafts).';


--
-- Name: exercise_attempts trg_update_user_stats_on_exercise; Type: TRIGGER; Schema: progress_tracking; Owner: gamilit_user
--

CREATE TRIGGER trg_update_user_stats_on_exercise AFTER INSERT ON progress_tracking.exercise_attempts FOR EACH ROW EXECUTE FUNCTION gamilit.update_user_stats_on_exercise_complete();


--
-- Name: exercise_submissions trg_update_user_stats_on_submission; Type: TRIGGER; Schema: progress_tracking; Owner: gamilit_user
--

CREATE TRIGGER trg_update_user_stats_on_submission AFTER UPDATE ON progress_tracking.exercise_submissions FOR EACH ROW WHEN (((new.status = ANY (ARRAY['graded'::text, 'reviewed'::text])) AND (new.is_correct = true) AND ((old.status IS DISTINCT FROM new.status) OR (old.is_correct IS DISTINCT FROM new.is_correct)))) EXECUTE FUNCTION gamilit.update_user_stats_on_submission_graded();


--
-- Name: TRIGGER trg_update_user_stats_on_submission ON exercise_submissions; Type: COMMENT; Schema: progress_tracking; Owner: gamilit_user
--

COMMENT ON TRIGGER trg_update_user_stats_on_submission ON progress_tracking.exercise_submissions IS 'Actualiza gamification_system.user_stats cuando una submission es calificada como correcta. Solo se ejecuta en transiciones de estado relevantes (submitted→graded, incorrect→correct). Complementa el trigger de exercise_attempts para mantener consistencia en el sistema de recompensas. Dispara la cadena: submission graded → user_stats updated → missions earn_xp updated.';


