--
-- Name: profiles profiles_read_admin; Type: POLICY; Schema: auth_management; Owner: gamilit_user
--

CREATE POLICY profiles_read_admin ON auth_management.profiles FOR SELECT USING (((EXISTS ( SELECT 1
   FROM auth_management.user_roles ur
  WHERE ((ur.user_id = (current_setting('app.current_user_id'::text, true))::uuid) AND (ur.role = 'super_admin'::auth_management.gamilit_role)))) AND (tenant_id = (current_setting('app.current_tenant_id'::text, true))::uuid)));


--
-- Name: POLICY profiles_read_admin ON profiles; Type: COMMENT; Schema: auth_management; Owner: gamilit_user
--

COMMENT ON POLICY profiles_read_admin ON auth_management.profiles IS 'Permite a los administradores ver todos los perfiles de su tenant';


