--
-- Name: profiles profiles_read_teacher; Type: POLICY; Schema: auth_management; Owner: gamilit_user
--

CREATE POLICY profiles_read_teacher ON auth_management.profiles FOR SELECT USING (((EXISTS ( SELECT 1
   FROM auth_management.user_roles ur
  WHERE ((ur.user_id = (current_setting('app.current_user_id'::text, true))::uuid) AND (ur.role = 'admin_teacher'::auth_management.gamilit_role)))) AND (role = 'student'::auth_management.gamilit_role) AND (id IN ( SELECT cm.student_id
   FROM (social_features.classroom_members cm
     JOIN social_features.classrooms c ON ((c.id = cm.classroom_id)))
  WHERE (c.teacher_id = (current_setting('app.current_user_id'::text, true))::uuid)))));


